@font-face {
  font-family: "Product Sans";
  src: url("/fonts/ProductSans-Regular.ttf") format("truetype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Product Sans";
  src: url("/fonts/ProductSans-Italic.ttf") format("truetype");
  font-weight: 400;
  font-style: italic;
  font-display: swap;
}

@font-face {
  font-family: "Product Sans";
  src: url("/fonts/ProductSans-Bold.ttf") format("truetype");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}

@font-face {
  font-family: "Product Sans";
  src: url("/fonts/ProductSans-BoldItalic.ttf") format("truetype");
  font-weight: 700;
  font-style: italic;
  font-display: swap;
}

:root {
  --primary: #0A2A5E;
  --primary-900: #061B3F;
  --primary-800: #082651;
  --primary-700: #11396F;
  --primary-100: #E8EEF7;
  --primary-50: #F4F7FB;
  --accent: #FFFFFF;
  --accent-900: #FFFFFF;
  --accent-700: #FFFFFF;
  --accent-500: #FFFFFF;
  --accent-100: #FFFFFF;
  --accent-50: #FFFFFF;
  --success: #1F8A5B;
  --success-bg: #DDF4E8;
  --warning: #B46A12;
  --warning-bg: #FFF0D1;
  --danger: #B23B3B;
  --danger-bg: #FCE3E3;
  --info: #2C6EB7;
  --info-bg: #E2EFFC;
  --purple: #7656A5;
  --purple-bg: #EEE6FA;
  --ink: #102039;
  --muted: #667085;
  --subtle: #98A2B3;
  --line: rgba(10, 42, 94, 0.12);
  --line-strong: rgba(10, 42, 94, 0.22);
  --white: #FFFFFF;
  --surface: rgba(255, 255, 255, 0.82);
  --surface-soft: rgba(255, 255, 255, 0.58);
  --page: #FFFFFF;
  --shadow-xs: none;
  --shadow-sm: none;
  --shadow-md: none;
  --inset: none;
  --pill: 12px;
  --color-primary: var(--primary);
  --color-primary-hover: var(--primary-700);
  --color-primary-soft: var(--primary-100);
  --color-bg-page: var(--page);
  --color-bg-app: #FFFFFF;
  --color-bg-panel: var(--surface);
  --color-bg-card: var(--accent-50);
  --color-text-main: var(--ink);
  --color-text-muted: var(--muted);
  --color-text-subtle: var(--subtle);
  --color-accent-lime: var(--accent);
  --color-accent-mint: #adb7c8;
  --color-accent-rose: #d99860;
  --color-accent-violet: #5c6d89;
  --color-accent-teal: #344a6e;
  --color-accent-apricot: var(--accent-700);
  --color-border: var(--line);
  --color-border-strong: var(--line-strong);
  --shadow-soft: var(--shadow-sm);
  --shadow-card: var(--shadow-xs);
  --shadow-inset: var(--inset);
  --radius-xs: 10px;
  --radius-sm: 14px;
  --radius-md: 18px;
  --radius-lg: 24px;
  --radius-xl: 32px;
  --radius-pill: var(--pill);
  --sidebar-width: 228px;
  --stroke-width: 1.9;
  --font-family: var(--font-product-sans), "Product Sans", Inter, Manrope, ui-sans-serif, system-ui, sans-serif;
  --overview-title: #0a2a5e;
  --overview-muted: #868c98;
  --overview-surface: #f6f8fa;
  --overview-border: #e2e4e9;
}

.booking-card-interactive {
  gap: 18px;
}

.doctor-rating-trigger {
  border: 0;
  border-radius: 999px;
  background: #eaf2ff;
  color: #16356d;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 10px 14px;
  cursor: pointer;
}

.doctor-rating-trigger strong,
.doctor-rating-trigger small {
  color: inherit;
}

.appointment-mobile-sheet {
  max-width: 380px;
  margin: 0 auto;
  display: grid;
  gap: 18px;
  padding-bottom: 16px;
}

.appointment-mobile-header {
  display: grid;
  grid-template-columns: 52px 1fr 52px;
  align-items: center;
  gap: 12px;
}

.appointment-mobile-header h2 {
  margin: 0;
  font-size: 2rem;
  text-align: center;
  color: #22314d;
}

.appointment-circle-button {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  border: 0;
  background: #ffffff;
  color: #22314d;
  font-size: 1.5rem;
  cursor: pointer;
  display: grid;
  place-items: center;
}

.appointment-circle-button-static {
  cursor: default;
}

.appointment-surface-card,
.appointment-summary-card {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.96), rgba(249, 246, 241, 0.96));
  border: 1px solid #eadfd0;
  border-radius: 28px;
  padding: 24px 20px;
  box-shadow: 0 18px 40px rgba(34, 49, 77, 0.08);
}

.appointment-surface-head h3,
.appointment-summary-card h3,
.confirmation-hero h3 {
  margin: 0;
  color: #22314d;
}

.appointment-surface-head p,
.confirmation-hero p {
  margin: 6px 0 0;
  color: #6c7485;
}

.appointment-date-strip {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 8px;
  margin-top: 22px;
}

.appointment-date-pill {
  border: 0;
  border-bottom: 3px solid transparent;
  background: transparent;
  color: #697286;
  padding: 10px 4px 14px;
  display: grid;
  gap: 8px;
  justify-items: center;
  cursor: pointer;
}

.appointment-date-pill.active {
  color: #16356d;
  border-bottom-color: #16356d;
}

.appointment-slot-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
  margin-top: 22px;
}

.appointment-slot-button {
  border: 1px solid #e2d7c8;
  border-radius: 18px;
  padding: 16px 10px;
  background: #faf8f4;
  color: #737b8b;
  cursor: pointer;
}

.appointment-slot-button.active {
  border-color: #16356d;
  color: #16356d;
  background: #ffffff;
  box-shadow: inset 0 0 0 1px #16356d;
}

.appointment-slot-button.is-disabled,
.appointment-slot-button:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.appointment-summary-card {
  display: grid;
  gap: 14px;
}

.customer-mtm-availability-screen .appointment-surface-card,
.customer-mtm-availability-screen .appointment-summary-card {
  background: #ffffff;
  box-shadow: none;
}

.customer-mtm-availability-screen {
  width: min(100%, 620px);
  margin-inline: auto;
  gap: 22px;
  background: #ffffff;
}

.customer-mtm-availability-back {
  justify-self: start;
  margin: 0;
}

.customer-mtm-calendar-card {
  width: 100%;
  margin: 0;
}

.customer-mtm-pharmacist-search {
  min-height: 76px;
  display: grid;
  place-items: center;
  align-content: center;
  gap: 10px;
  color: #0a2a5e;
  font-size: 15px;
  font-weight: 600;
  text-align: center;
}

.customer-mtm-pharmacist-search .nevari-branded-spinner {
  width: 32px;
  height: 32px;
}

.customer-mtm-pharmacist-search .nevari-branded-spinner::after {
  width: 32px;
  height: 32px;
}

.customer-mtm-review-skip-note {
  margin: 14px 0 0;
  padding: 12px 14px;
  border-radius: 12px;
  background: #f4f7fb;
  color: #40516e;
  line-height: 1.5;
}

.appointment-summary-row,
.checkout-summary-grid div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  color: #6c7485;
}

.appointment-summary-row strong,
.checkout-summary-grid strong {
  color: #22314d;
}

.appointment-duration-field,
.appointment-reason-field {
  display: grid;
  gap: 8px;
  color: #6c7485;
  font-size: 13px;
}

.appointment-duration-field select,
.appointment-reason-field textarea {
  width: 100%;
  border: 1px solid #e2d7c8;
  border-radius: 16px;
  background: #fffdfa;
  color: #22314d;
  padding: 12px 14px;
  font: inherit;
}

.appointment-reason-field textarea {
  min-height: 88px;
  resize: vertical;
}

.appointment-primary-cta,
.appointment-link-cta {
  min-width: 100%;
  border: 0;
  border-radius: 999px;
  background: #16356d;
  color: #ffffff;
  padding: 18px 20px;
  text-align: center;
  text-decoration: none;
  font-weight: 700;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.appointment-primary-cta:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.appointment-cta-spinner {
  width: 24px;
  height: 24px;
  border: 3px solid rgba(255, 255, 255, 0.35);
  border-top-color: #ffffff;
  border-radius: 999px;
  animation: appointmentCtaSpin 780ms linear infinite;
}

.appointment-cta-loading {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  max-width: 100%;
}

.appointment-cta-loading-text {
  display: inline-block;
  font-size: 0.94rem;
  font-weight: 600;
  line-height: 1.2;
  white-space: normal;
  text-align: center;
}

@keyframes appointmentCtaSpin {
  to {
    transform: rotate(360deg);
  }
}

.appointment-secondary-cta {
  width: 100%;
  border: 1px solid #d7ccb9;
  border-radius: 18px;
  background: #f5efe6;
  color: #16356d;
  padding: 18px 20px;
  font-weight: 700;
  cursor: pointer;
}

.checkout-summary-grid {
  display: grid;
  gap: 14px;
}

.checkout-status-banner {
  margin: 22px 0;
  border-radius: 22px;
  background: #f5efe6;
  padding: 16px 18px;
  display: grid;
  gap: 6px;
  color: #6c7485;
}

.checkout-status-banner strong {
  color: #16356d;
}

.confirmation-hero {
  text-align: center;
  display: grid;
  gap: 10px;
  margin-bottom: 22px;
}

.confirmation-badge {
  width: 64px;
  height: 64px;
  border-radius: 20px;
  margin: 0 auto;
  display: grid;
  place-items: center;
  background: #eaf2ff;
  color: #16356d;
  font-weight: 800;
}

.calendar-action-stack {
  display: grid;
  gap: 12px;
  margin-top: 22px;
}

.review-bar-row {
  display: grid;
  grid-template-columns: 28px 1fr 82px;
  align-items: center;
  gap: 12px;
  margin-bottom: 18px;
}

.review-bar-label {
  display: grid;
  justify-items: center;
  color: #6c7485;
}

.review-bar-track {
  height: 6px;
  background: #e4ddd4;
  border-radius: 999px;
  overflow: hidden;
}

.review-bar-track span {
  display: block;
  height: 100%;
  background: #16356d;
  border-radius: 999px;
}

.review-bar-text {
  color: #6c7485;
}

.review-list-stack {
  display: grid;
  gap: 16px;
}

.review-entry-card {
  background: #ffffff;
  border: 1px solid #eadfd0;
  border-radius: 24px;
  padding: 18px;
  box-shadow: 0 12px 32px rgba(34, 49, 77, 0.06);
}

.review-entry-head {
  display: grid;
  grid-template-columns: 52px 1fr auto;
  gap: 14px;
  align-items: center;
  margin-bottom: 12px;
}

.review-entry-avatar {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: #dbe4ef;
  color: #22314d;
  display: grid;
  place-items: center;
  font-weight: 700;
}

.review-rating-pill {
  border-radius: 999px;
  background: #eaf2ff;
  color: #16356d;
  padding: 10px 14px;
  font-weight: 700;
}

.review-star-picker {
  display: flex;
  gap: 8px;
  margin: 16px 0;
}

.review-star-picker button {
  border: 0;
  background: #ebe4d9;
  color: #9a8f7f;
  width: 42px;
  height: 42px;
  border-radius: 14px;
  font-size: 1.2rem;
  cursor: pointer;
}

.review-star-picker button.active {
  background: #16356d;
  color: #ffffff;
}

.review-textarea {
  width: 100%;
  border: 1px solid #ded4c6;
  border-radius: 18px;
  padding: 14px 16px;
  resize: vertical;
  min-height: 120px;
  margin-bottom: 16px;
  font: inherit;
}

@media (max-width: 720px) {
  .appointment-mobile-sheet {
    max-width: none;
  }

  .appointment-mobile-header h2 {
    font-size: 1.8rem;
  }

  .appointment-slot-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

.doctor-consultation-layout,
.doctor-reviews-layout,
.doctor-availability-shell {
  display: grid;
  gap: 20px;
}

.doctor-consultation-layout {
  grid-template-columns: minmax(280px, 340px) minmax(0, 1fr);
  align-items: flex-start;
}

.doctor-appointment-stack {
  display: grid;
  gap: 16px;
}

.doctor-appointment-detail-card {
  background: #fff;
  border: 1px solid #e6ddcf;
  border-radius: 24px;
  padding: 20px;
  box-shadow: 0 14px 30px rgba(34, 49, 77, 0.07);
  display: grid;
  gap: 16px;
}

.doctor-appointment-detail-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
}

.doctor-appointment-detail-head h3,
.doctor-review-summary-head h2 {
  margin: 0;
  color: #22314d;
}

.doctor-appointment-detail-head p {
  margin: 6px 0 0;
  color: #6c7485;
}

.doctor-appointment-status-group {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: flex-end;
}

.doctor-appointment-grid,
.doctor-profile-metrics,
.doctor-overview-insights,
.doctor-availability-grid {
  display: grid;
  gap: 14px;
}

.doctor-appointment-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.doctor-appointment-grid div,
.doctor-profile-metrics article,
.doctor-insight-card {
  border-radius: 18px;
  background: #f7f2eb;
  padding: 14px 16px;
  display: grid;
  gap: 6px;
}

.doctor-appointment-grid span,
.doctor-profile-metrics span,
.doctor-insight-card span,
.doctor-availability-time-grid span {
  color: #6c7485;
  font-size: 0.88rem;
}

.doctor-appointment-grid strong,
.doctor-profile-metrics strong,
.doctor-insight-card strong {
  color: #22314d;
}

.doctor-appointment-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.doctor-review-summary-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  margin-bottom: 18px;
}

.doctor-review-average {
  border-radius: 20px;
  background: #eaf2ff;
  padding: 14px 18px;
  text-align: center;
  color: #16356d;
  display: grid;
}

.doctor-review-average strong {
  font-size: 1.5rem;
}

.doctor-availability-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 14px;
}

.doctor-availability-note {
  margin: 14px 0 0;
  color: #6c7485;
  font-size: 0.95rem;
}

.doctor-availability-card {
  border: 1px solid #e6ddcf;
  border-radius: 22px;
  padding: 16px;
  display: grid;
  gap: 14px;
}

.doctor-availability-head {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}

.doctor-availability-pill-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(84px, 1fr));
  gap: 12px;
}

.doctor-availability-pill-grid.is-disabled {
  opacity: 0.45;
}

.doctor-availability-pill {
  border: 1px solid #ded4c6;
  border-radius: 999px;
  padding: 9px 10px;
  font: inherit;
  background: #fff;
  color: #22314d;
  min-height: 42px;
  transition: transform 0.15s ease, border-color 0.15s ease, background 0.15s ease, color 0.15s ease, box-shadow 0.15s ease;
}

.doctor-availability-pill.active {
  border-color: #16356d;
  background: #16356d;
  color: #fff;
  box-shadow: 0 10px 24px rgba(22, 53, 109, 0.18);
}

.doctor-availability-pill:disabled {
  cursor: not-allowed;
}

.doctor-availability-pill:not(:disabled):hover {
  transform: translateY(-1px);
}

.doctor-switch {
  position: relative;
  width: 50px;
  height: 28px;
  display: inline-block;
}

.doctor-switch input {
  opacity: 0;
  width: 0;
  height: 0;
}

.doctor-switch span {
  position: absolute;
  inset: 0;
  border-radius: 999px;
  background: #d6cec1;
  transition: background 0.2s ease;
}

.doctor-switch span::after {
  content: "";
  position: absolute;
  top: 3px;
  left: 3px;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: #fff;
  transition: transform 0.2s ease;
}

.doctor-switch input:checked+span {
  background: #16356d;
}

.doctor-switch input:checked+span::after {
  transform: translateX(22px);
}

.doctor-overview-insights {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  margin-bottom: 20px;
}

.doctor-insight-card small {
  color: #6c7485;
}

.doctor-card-clickable {
  cursor: pointer;
}

.doctor-profile-metrics {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin-top: 18px;
}

@media (max-width: 900px) {

  .doctor-consultation-layout,
  .doctor-overview-insights,
  .doctor-availability-grid,
  .doctor-profile-metrics {
    grid-template-columns: 1fr;
  }

  .doctor-appointment-grid {
    grid-template-columns: 1fr;
  }
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: auto;
}

body {
  margin: 0;
  min-height: 100vh;
  font-family: var(--font-family);
  color: var(--color-text-main);
  background:
    radial-gradient(circle at 18% 12%, rgba(255, 255, 255, 0.54), transparent 30%),
    radial-gradient(circle at 84% 8%, rgba(216, 202, 182, 0.3), transparent 20%),
    radial-gradient(circle at 82% 78%, rgba(173, 183, 200, 0.18), transparent 18%),
    var(--color-bg-page);
  padding: 26px;
}

body.auth-locked,
body.modal-open {
  overflow: hidden;
  height: 100vh;
}

button,
input,
select {
  font: inherit;
}

button {
  border: 0;
  cursor: pointer;
}

svg {
  width: 18px;
  height: 18px;
  fill: none;
  stroke: currentColor;
  stroke-linecap: round;
  stroke-linejoin: round;
  stroke-width: var(--stroke-width);
}

.icon-sprite {
  position: absolute;
  width: 0;
  height: 0;
  overflow: hidden;
}

.page-shell {
  width: min(1480px, 100%);
  margin: 0 auto;
  display: grid;
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr);
  gap: 18px;
  transition: filter 220ms ease, transform 220ms ease;
}

body.auth-locked .page-shell {
  filter: blur(10px);
  transform: scale(0.99);
  pointer-events: none;
  user-select: none;
}

body.modal-open .page-shell {
  filter: none;
  transform: none;
  pointer-events: auto;
  user-select: auto;
}

.sidebar,
.main-shell {
  background: rgba(248, 245, 239, 0.82);
  border: 1px solid rgba(255, 255, 255, 0.56);
  box-shadow: var(--shadow-soft);
  backdrop-filter: blur(16px);
}

.sidebar {
  border-radius: var(--radius-xl);
  padding: 22px 18px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: calc(100vh - 52px);
  position: sticky;
  top: 26px;
  background: #ffffff;
}

.brand-row {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 28px;
}

.brand-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 14px;
  background: linear-gradient(135deg, rgba(14, 41, 85, 0.96), rgba(52, 74, 110, 0.82));
  color: #fff;
  font-weight: 700;
}

.brand-row strong,
.user-meta strong,
.legend-item strong,
.mini-stat strong,
.history-card strong,
.audit-detail strong,
.sidebar-card strong {
  display: block;
}

.brand-row span,
.user-meta span,
.legend-item span,
.mini-stat small,
.history-card span,
.sidebar-card span,
.spotlight-card span,
.audit-detail p {
  color: var(--color-text-muted);
}

.nav-groups {
  display: grid;
  gap: 20px;
}

.nav-label,
.section-kicker,
.eyebrow {
  margin: 0 0 10px;
  font-size: 10px;
  text-transform: uppercase;
  letter-spacing: -0.01em;
  color: var(--color-text-muted);
  font-weight: 800;
}

.nav-item {
  width: 100%;
  min-height: 40px;
  display: flex;
  align-items: center;
  gap: 13px;
  border-radius: var(--radius-pill);
  padding: 0 14px;
  margin-bottom: 6px;
  background: transparent;
  color: var(--color-text-main);
  text-align: left;
  font-size: 12px;
  font-weight: 600;
}

.nav-item:hover,
.pill-button:hover,
.icon-button:hover,
.button-primary:hover,
.segment:hover {
  filter: none;
}

.nav-item.active {
  background: var(--color-primary);
  color: #fff;
