.role-shell .status-lane span {
  color: var(--role-muted);
  font-size: 12px;
  font-weight: 700;
}

.role-status-row strong {
  display: block;
  margin-top: 10px;
  font-size: 24px;
}

.role-shell .table-panel {
  padding: 18px;
}

.role-shell th {
