.role-shell .role-profile h2 {
  color: var(--role-text);
  font-size: 24px;
}

.role-app-header,
.role-profile-mini,
.role-icon-cluster,
.role-appointment-card,
.role-consultation-card {
  display: flex;
  align-items: center;
}

.role-app-header {
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}

.role-profile-mini {
  gap: 12px;
}

.role-profile-mini div {
  display: grid;
  gap: 2px;
}

.role-profile-mini small,
.role-doctor-strip small,
.role-consultation-card small,
.role-plan-card small,
.role-appointment-card small {
  color: var(--role-muted);
}

.role-profile-mini strong {
  color: var(--role-text);
  font-size: 16px;
}

.role-avatar {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--role-secondary), var(--role-accent-blue));
  color: var(--role-primary);
  font-size: 13px;
  font-weight: 800;
  box-shadow: var(--role-soft-shadow);
  flex: 0 0 auto;
}

.role-avatar.doctor {
  color: #fff;
  background: linear-gradient(135deg, var(--role-primary), var(--role-secondary));
}

.role-avatar.compact {
  width: 38px;
  height: 38px;
  font-size: 11px;
}

.role-icon-cluster {
  gap: 8px;
}

.role-icon-circle {
  width: 38px;
  height: 38px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: #fff;
  border: 1px solid var(--role-border);
  box-shadow: var(--role-soft-shadow);
  color: transparent;
  position: relative;
}

.role-icon-circle::before {
  color: var(--role-text);
  font-size: 12px;
  font-weight: 800;
}

.role-icon-circle:first-child::before {
  content: "S";
}

.role-icon-circle.role-icon-alert::before {
  content: "N";
}

.role-icon-alert::after {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #b96b5f;
  border: 2px solid #fff;
  position: absolute;
  right: 4px;
  top: 4px;
}

.role-search-card {
  min-height: 44px;
  display: flex;
  align-items: center;
  margin-bottom: 16px;
  padding: 0 16px;
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, 0.94);
  border: 1px solid var(--role-border);
  box-shadow: var(--role-soft-shadow);
  color: var(--role-muted);
  font-size: 13px;
}

