  box-shadow: var(--role-card-shadow);
}

.role-category-card.accent-blue {
  background: linear-gradient(135deg, #eff5fc, var(--role-accent-blue));
}

.role-category-card.accent-sand {
  background: linear-gradient(135deg, var(--role-secondary-soft), var(--role-accent-sand));
}

.role-category-card.accent-peach {
  background: linear-gradient(135deg, var(--role-accent-peach), var(--role-secondary));
