body:has(.role-shell-exact) {
  background: #fff;
}

.role-shell-exact {
  --color-primary: #0a2a5e;
  --color-primary-soft: #dde7f2;
  --color-primary-dark: #061b3c;
  --color-secondary: #e5d7c6;
  --color-secondary-soft: #f6efe7;
  --color-accent-yellow: #cdb98d;
  --color-accent-mint: #ede4d7;
  --color-accent-pink: #d7c1b4;
  --color-accent-blue: #bfd0e5;
  --color-accent-peach: #f1e3d4;
  --color-bg-2: #faf8f5;
  --color-surface-soft: #f8f4ee;
  --color-text: #07182f;
  --color-text-muted: #6e7480;
  --color-text-light: #a8aeb7;
  --color-border: #ebe4da;
  --color-dark: #0a2a5e;
  --color-danger: #b96b5f;
