.desktop-dashboard-shell {
  display: grid;
  gap: 12px;
  min-height: calc(100vh - 52px);
  min-height: calc(100dvh - 52px);
  height: 100%;
  grid-template-rows: auto auto minmax(0, 1fr) auto;
}

.desktop-dashboard-top-content {
  grid-row: 1;
}

.desktop-dashboard-header {
  grid-row: 2;
}

.desktop-dashboard-screen {
  grid-row: 3;
}

.desktop-bottom-nav {
  grid-row: 4;
