}

.customer-reviews-grid {
  display: grid;
  gap: 16px;
}

.customer-reviews-summary,
.customer-reviews-compose,
.customer-reviews-list {
  width: 100%;
}

.customer-reviews-feedback {
  margin: 0;
}

.customer-overview-reference-shell {
