  margin: 0 auto;
  display: grid;
  gap: 20px;
}

.customer-overview-reference-head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
}

.customer-overview-reference-head p {
  margin: 0 0 6px;
  color: #8b97aa;
  font-size: 14px;
}

.customer-overview-reference-head h1 {
  margin: 0;
  color: #0a2a5e;
  font-size: clamp(28px, 3vw, 36px);
  line-height: 1;
  font-weight: 500;
}

.customer-overview-store-link {
  min-height: 38px;
  padding: 0 14px;
  border-radius: 999px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid #dfe4ec;
  background: #fff;
  color: #0a2a5e;
  text-decoration: none;
  font-size: 12px;
  font-weight: 600;
}

.customer-overview-search {
  margin: 0;
  min-height: 54px;
  border-radius: 999px;
  border-color: #dfe4ec;
  background: #fff;
  box-shadow: none;
}

.customer-overview-search-results {
  margin: -8px 0 0;
}

.customer-overview-reference-stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.customer-overview-reference-card {
  min-height: 142px;
  padding: 18px;
  border-radius: 16px;
  border: 1px solid #dfe4ec;
  background: #f8fafc;
  display: grid;
  align-content: start;
  gap: 10px;
}

.customer-overview-reference-card span {
  color: #8b97aa;
  font-size: 13px;
}

.customer-overview-reference-card strong {
  color: #0a2a5e;
  font-size: 18px;
  font-weight: 600;
  line-height: 1.1;
}

.customer-overview-reference-icon {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid #dfe4ec;
  background: #fff;
  color: #0a2a5e;
  display: grid;
  place-items: center;
}

.customer-overview-reference-list {
  display: grid;
  gap: 16px;
}

.customer-overview-reference-list-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.customer-overview-reference-list-head h2 {
  margin: 0;
  color: #111827;
  font-size: 28px;
  font-weight: 400;
}

.customer-overview-reference-table-head {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 84px;
  gap: 12px;
  color: #9aa4b4;
  font-size: 12px;
}

.customer-overview-reference-table-head span:last-child {
  text-align: center;
}

.customer-overview-reference-rows {
  display: grid;
}

.customer-overview-reference-row {
  width: 100%;
  padding: 18px 0;
  border-bottom: 1px solid #eef2f6;
  background: transparent;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 84px;
  align-items: center;
  gap: 12px;
  text-align: left;
}

.customer-overview-reference-row:last-child {
  border-bottom: 0;
}

.customer-overview-reference-item {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 14px;
}

.customer-overview-reference-thumb {
  width: 48px;
  height: 48px;
  border-radius: 12px;
  overflow: hidden;
  flex: 0 0 auto;
  background: #eef2f6;
}

.customer-overview-reference-thumb img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.customer-overview-reference-copy {
  min-width: 0;
  display: grid;
  gap: 4px;
}

.customer-overview-reference-copy strong {
  color: #111827;
  font-size: 16px;
  font-weight: 500;
  overflow-wrap: anywhere;
}

.customer-overview-reference-copy span {
  color: #ff9f1a;
  font-size: 13px;
}

.customer-overview-reference-count {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  margin-left: auto;
  background: #f4f6f8;
  color: #111827;
  display: grid;
  place-items: center;
  font-size: 13px;
  font-weight: 500;
}

.customer-overview-reference-empty {
  padding: 18px;
  border-radius: 16px;
  border: 1px solid #dfe4ec;
  background: #f8fafc;
  color: #8b97aa;
  font-size: 14px;
}

@media (min-width: 981px) {
  .customer-reviews-shell {
    max-width: 1120px;
  }

  .customer-reviews-grid {
    grid-template-columns: minmax(0, 1fr) minmax(320px, 360px);
    align-items: flex-start;
  }

  .customer-reviews-summary {
    grid-column: 1 / 2;
  }

  .customer-reviews-compose {
    grid-column: 2 / 3;
  }

  .customer-reviews-feedback {
    grid-column: 1 / -1;
  }

  .customer-reviews-list {
    grid-column: 1 / -1;
  }
}

@media (max-width: 980px) {
  .desktop-dashboard-page {
    width: 100%;
  }

  .desktop-dashboard-shell {
    min-height: calc(100vh - 52px);
