    grid-template-rows: auto auto minmax(0, 1fr) auto;
  }

  .desktop-dashboard-screen {
    min-height: 0;
    height: 100%;
    padding: 20px 20px 16px;
  }

  .role-shell-exact .screen-scroll {
    padding-bottom: 104px;
  }

  .role-split {
    grid-template-columns: 1fr;
  }

  .role-shell .sidebar {
    z-index: 42;
  }

  .role-sidebar-backdrop {
