    align-items: flex-start;
    flex-direction: column;
  }

  .customer-overview-reference-stats {
    grid-template-columns: 1fr;
  }

  .customer-overview-reference-row,
  .customer-overview-reference-table-head {
    grid-template-columns: minmax(0, 1fr) 60px;
  }

  body:has(.role-shell-exact) {
    height: 100dvh;
    overflow: hidden;
    padding: 0;
  }

  .desktop-dashboard-page {
    min-height: 100dvh;
    height: 100dvh;
    overflow: hidden;
    width: 100%;
  }

  .desktop-dashboard-shell {
    min-height: 100dvh;
    height: 100dvh;
    grid-template-rows: auto auto minmax(0, 1fr);
    overflow: hidden;
    padding: 10px 10px 0;

  }

  .desktop-dashboard-screen {
    min-height: 0;
    height: 100%;
    padding: 10px 10px 12px;
    border-radius: 0px;
