    overflow: hidden;
  }

  .role-shell-exact .desktop-dashboard-screen {
    overflow: hidden;
  }

  .role-shell-exact .screen-scroll {
    height: 100%;
    overflow-y: auto;
    overflow-x: hidden;
    padding-bottom: calc(96px + env(safe-area-inset-bottom, 0px));
    -webkit-overflow-scrolling: touch;
    overscroll-behavior: contain;
  }

  .desktop-dashboard-title {
    font-size: 22px;
    line-height: 1;
  }


  .role-shell-exact .category-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .appointment-stack-track {
    grid-auto-columns: minmax(280px, 88vw);
    gap: 30px;
  }

  .appointment-stack-card {
    margin-left: calc(var(--stack, 0) * -18px);
  }

  .desktop-dashboard-header {
    align-items: flex-start;
    flex-direction: column;
    margin-top: 4px;
    margin-left: 6px;
  }

  .desktop-bottom-nav {
    width: fit-content;
  }

  .customer-overview-grid,
  .customer-doctor-list,
  .customer-profile-grid {
    grid-template-columns: 1fr;
  }

  .customer-appointment-highlight,
  .customer-appointment-card {
    grid-template-columns: 1fr;
    align-items: flex-start;
    min-width: 0;
  }

  .customer-appointment-side {
    justify-items: start;
  }

  .customer-list-shell,
  .customer-panel-card,
  .customer-profile-hero {
    padding: 14px;
  }

  .customer-profile-hero {
    justify-content: space-between;
  }

  .customer-panel-head {
    margin-bottom: 10px;
    gap: 8px;
  }

  .customer-panel-head h2 {
    font-size: 19px;
    line-height: 1.25;
  }

  .customer-section-kicker {
    margin-bottom: 4px;
  }

  .customer-filter-bar {
    margin-bottom: 12px;
  }

  .customer-appointment-card-slide {
    flex: 0 0 min(84vw, 292px);
    min-width: min(84vw, 292px);
    max-width: min(84vw, 292px);
    border-radius: 18px;
  }

  .customer-status-grid {
    grid-template-columns: 1fr;
  }

  .customer-persistent-app-header {
    margin-bottom: 8px;
  }

  .role-shell-exact .bottom-nav {
    position: fixed;
    left: 50%;
    right: auto;
    transform: translateX(-50%);
    bottom: max(12px, env(safe-area-inset-bottom, 0px));
    min-height: 58px;
    background: rgba(255, 255, 255, 0.9);
    border: 1px solid var(--color-border);
    box-shadow: var(--shadow-floating);
    border-radius: 28px;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    padding: 7px;
    gap: 8px;
    overflow-x: auto;
    scrollbar-width: none;
    backdrop-filter: blur(16px);
    z-index: 80;
  }

  .role-shell-exact .bottom-nav::-webkit-scrollbar {
    display: none;
  }

  .role-shell-exact .bottom-nav .nav-item {
    flex: 0 0 auto;
  }

  .desktop-bottom-nav {
    width: fit-content;
    max-width: calc(100vw - 32px);
  }

  .customer-settings-grid-design,
  .customer-profile-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {

  .customer-list-shell,
  .customer-panel-card,
  .customer-profile-hero,
  .customer-order-card,
  .customer-appointment-card {
    border-radius: 20px;
  }

  .customer-panel-head h2,
  .customer-profile-hero h2 {
    font-size: 17px;
  }

  .customer-appointment-card-slide {
    flex: 0 0 min(88vw, 268px);
    min-width: min(88vw, 268px);
    max-width: min(88vw, 268px);
    padding: 9px;
  }
}

@media (min-width: 981px) {
  .desktop-dashboard-shell {
    grid-template-columns: 240px minmax(0, 1fr);
    grid-template-rows: auto minmax(0, 1fr);
    align-items: flex-start;
  }

  .dashboard-side-nav {
    position: sticky;
    top: 24px;
    min-height: calc(100vh - 48px);
    display: grid;
    align-content: start;
    gap: 0;
    padding: 20px;
    border-radius: 10px;
    border: 1px solid rgba(235, 228, 218, 0.92);
    background: linear-gradient(180deg, rgba(250, 248, 245, 0.98), rgba(248, 244, 238, 0.98));
    box-shadow: none;
    grid-row: 1 / span 2;
  }

  .desktop-dashboard-header,
  .desktop-dashboard-screen,
  .desktop-bottom-nav {
    grid-column: 2;
  }

  .desktop-dashboard-header {
    grid-row: 1;
  }

  .desktop-dashboard-screen {
    grid-row: 2;
  }

  .customer-persistent-app-header,
  .desktop-dashboard-top-content,
  .role-shell-exact .desktop-bottom-nav {
    display: none;
  }

  .customer-quick-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .customer-overview-grid {
    grid-template-columns: minmax(0, 1.1fr) minmax(320px, 0.9fr);
  }
}

@media (max-width: 980px) {
  .dashboard-side-nav {
    display: none;
  }

  .desktop-dashboard-top-content {
    display: grid;
  }

  .customer-stats-row {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (min-width: 721px) and (max-width: 980px) {
  .desktop-dashboard-shell {
    grid-template-rows: auto auto auto minmax(0, 1fr);
  }

  .dashboard-tablet-toolbar {
    display: flex;
    justify-content: flex-start;
    grid-row: 1;
  }

  .desktop-dashboard-top-content {
    grid-row: 2;
  }

  .desktop-dashboard-header {
    grid-row: 3;
  }

  .desktop-dashboard-screen {
    grid-row: 4;
  }

  .dashboard-side-nav {
    position: fixed;
    inset: 16px auto 16px 16px;
    z-index: 30;
    width: min(300px, calc(100vw - 32px));
    display: grid;
    align-content: start;
    padding: 20px;
    border-radius: 10px;
    border: 1px solid rgba(235, 228, 218, 0.92);
    background: linear-gradient(180deg, rgba(250, 248, 245, 0.99), rgba(248, 244, 238, 0.99));
    box-shadow: var(--shadow-floating);
    transform: translateX(calc(-100% - 24px));
    transition: transform 180ms ease;
  }

  .dashboard-side-nav.is-open {
    transform: translateX(0);
  }

  .dashboard-side-nav-backdrop {
    position: fixed;
    inset: 0;
    z-index: 29;
    display: block;
    background: rgba(7, 24, 47, 0.18);
  }

  .role-shell-exact .desktop-bottom-nav {
    display: none;
  }

  .role-shell-exact .screen-scroll {
    padding-bottom: 18px;
  }
}

@media (max-width: 640px) {
  .customer-stats-row {
    gap: 8px;
  }

  .customer-stat-card {
    min-height: 94px;
    padding: 12px 10px;
  }

  .customer-stat-card strong {
    font-size: 20px;
    line-height: 28px;
  }

  .customer-order-summary {
    flex-direction: column;
    align-items: stretch;
  }

  .customer-order-side {
    align-items: flex-start;
  }
}

.status-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}

.good {
  background: #b9996d;
}

.warn {
  background: #d8cab6;
}

.ok {
  background: #5c6d89;
}

.bad {
  background: #d99860;
}

.metrics-grid,
.operations-grid,
.analytics-grid,
.dual-table-grid {
  display: flex;
  gap: 18px;
  margin-bottom: 18px;
}




.metric-card {
  min-height: 148px;
  padding: 18px;
  position: relative;
  overflow: hidden;
}

.metric-card::after {
  content: "";
  position: absolute;
  right: -22px;
  bottom: -28px;
  width: 110px;
  height: 110px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.18);
}

.metric-card.lime {
  background: linear-gradient(135deg, #efe4d4, #d8cab6);
}

.metric-card.mint {
  background: linear-gradient(135deg, #dce4ef, #adb7c8);
}

.metric-card.rose {
  background: linear-gradient(135deg, #ebc39f, #d99860);
}

.metric-card.violet {
  background: linear-gradient(135deg, #7d8ca5, #5c6d89);
}

.metric-row,
.panel-header,
.toolbar,
.spotlight-head {
  justify-content: space-between;
  gap: 12px;
}

.metric-label,
.stack-row span,
.mini-stat span,
.history-meta span,
.audit-pill,
th,
td,
.audit-detail p,
.section-kicker {
  font-size: 12px;
}

.metric-card strong {
  display: block;
  margin-top: 12px;
  font-size: 32px;
  line-height: 1;
}

.metric-card small {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 12px;
  position: relative;
  z-index: 1;
  color: rgba(14, 41, 85, 0.72);
  font-weight: 600;
}

.analytics-grid {
  grid-template-columns: minmax(0, 1.25fr) minmax(320px, 0.92fr);
}


.dual-table-grid {
  grid-template-columns: 1.08fr 0.92fr;
}

.panel,
.table-panel {
  background: rgba(255, 255, 255, 0.28);
  padding: 20px;
}

.dashboard-stats-shell,
.dashboard-table-shell {
  background: transparent !important;
  border: 0 !important;
  box-shadow: none !important;
}

.dashboard-stats-shell {
  padding: 0 !important;
}

.dashboard-table-shell {
  padding: 0 !important;
}

.panel h2 {
  margin: 2px 0 0;
  font-size: 22px;
  line-height: 1.2;
}

.compact h2 {
  font-size: 18px;
}

.segmented {
  gap: 8px;
  padding: 4px;
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, 0.3);
}

.segment {
  min-width: 72px;
  padding: 0 14px;
  color: var(--color-text-main);
  background: transparent;
  font-weight: 600;
}

.bar-chart {
  margin-top: 22px;
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 12px;
  min-height: 260px;
  align-items: flex-end;
}

.bar-col {
  display: grid;
  justify-items: center;
  gap: 10px;
}

.bar-shell {
  width: 100%;
  max-width: 62px;
  height: 208px;
  border-radius: 999px 999px 18px 18px;
  background: rgba(14, 41, 85, 0.07);
  display: flex;
  align-items: flex-end;
  padding: 8px;
}

.bar-fill {
  width: 100%;
  border-radius: 999px 999px 18px 18px;
  background-image: repeating-linear-gradient(-45deg, rgba(255, 255, 255, 0.34) 0 2px, transparent 2px 8px);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.55);
}

.bar-note {
  text-align: center;
}

.bar-note strong {
  display: block;
  font-size: 14px;
}

.bar-note span {
  color: var(--color-text-muted);
  font-size: 11px;
}

.trend-chart {
  margin-top: 18px;
  display: grid;
  gap: 16px;
  min-width: 720px;
}

.trend-chart-surface {
  min-height: 220px;
  border-radius: 24px;
  padding: 8px 10px 0;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.74), rgba(244, 248, 252, 0.42));
  border: 1px solid rgba(22, 53, 109, 0.08);
}

.trend-chart-svg {
  width: 100%;
  height: 220px;
  display: block;
  overflow: visible;
}

.trend-chart-grid-line {
  stroke: rgba(22, 53, 109, 0.08);
  stroke-width: 1;
  stroke-dasharray: 4 8;
}

.trend-chart-grid-line-base {
  stroke: rgba(22, 53, 109, 0.16);
  stroke-dasharray: none;
}

.trend-chart-area {
  pointer-events: none;
}

.trend-chart-line {
  fill: none;
  stroke: #16356d;
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.trend-chart-point-halo {
  fill: rgba(22, 53, 109, 0.12);
}

.trend-chart-point {
  stroke: rgba(255, 255, 255, 0.92);
  stroke-width: 2;
}

.trend-chart-point.placeholder,
.trend-chart-point-halo.placeholder {
  opacity: 0.45;
}

.trend-chart-notes {
  display: grid;
  gap: 12px;
}

.trend-chart-note {
  display: grid;
  justify-items: center;
  gap: 4px;
  text-align: center;
}

.trend-chart-note strong {
  display: block;
  font-size: 12px;
  letter-spacing: -0.02em;
  color: #16356d;
  white-space: nowrap;
}

.trend-chart-note span {
  color: var(--color-text-muted);
  font-size: 11px;
}

.trend-chart-note small {
  color: var(--color-text-muted);
  font-size: 11px;
}

.mix-layout {
  display: grid;
  grid-template-columns: minmax(200px, 0.7fr) 1fr;
  gap: 16px;
  align-items: center;
  min-height: 292px;
}

.donut-wrap {
  display: grid;
  place-items: center;
}

.donut-chart {
  width: 214px;
  height: 214px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background:
    radial-gradient(circle, rgba(248, 245, 239, 0.96) 0 42%, transparent 43%),
    conic-gradient(var(--color-accent-teal) 0 26%,
      var(--color-accent-rose) 26% 46%,
      var(--color-accent-lime) 46% 84%,
      var(--color-accent-violet) 84% 100%);
}

.donut-center {
  width: 120px;
  height: 120px;
  border-radius: 50%;
  background: rgba(248, 245, 239, 0.95);
  display: grid;
  place-items: center;
  text-align: center;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

.donut-center strong {
  display: block;
  font-size: 28px;
  margin-top: 6px;
}

.legend-list,
.stack-list,
.history-list {
  display: grid;
  gap: 12px;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 12px;
  border-radius: 18px;
  background: rgba(255, 255, 255, 0.34);
}

.legend-swatch {
  width: 14px;
  height: 14px;
  border-radius: 50%;
}

.legend-swatch.teal {
  background: var(--color-accent-teal);
}

.legend-swatch.rose {
  background: var(--color-accent-rose);
}

.legend-swatch.lime {
  background: var(--color-accent-lime);
}

.legend-swatch.violet {
  background: var(--color-accent-violet);
}

.stack-row {
  display: flex;
  justify-content: space-between;
  gap: 12px;
}

.mini-stat-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}


.history-card,
.status-lane,
.audit-detail,
.audit-detail-empty {
  background: rgba(255, 255, 255, 0.38);
  border: 1px solid rgba(255, 255, 255, 0.5);
  border-radius: 18px;
}

.mini-stat {
  padding: 14px;
}

.mini-stat strong {
  margin-top: 8px;
  font-size: 26px;
}

.table-scroll {
  overflow-x: auto;
}

table {
  width: 100%;
  border-collapse: collapse;
}

th {
  text-align: left;
  padding: 0 0 14px;
  color: var(--color-text-main);
  font-weight: 700;
}

td {
  padding: 14px 0;
  border-top: 1px solid rgba(14, 41, 85, 0.08);
  vertical-align: top;
}

.table-title {
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.table-title strong {
  font-size: 13px;
}

.muted {
  color: var(--color-text-muted);
}

.status-pill,
.audit-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 28px;
  padding: 0 12px;
  border-radius: var(--radius-pill);
  background: #E2EFFC;
  border: 1px solid rgba(44, 110, 183, 0.22);
  color: #2c6eb7;
  font-size: 12px;
  font-weight: 400;
  letter-spacing: -0.01em;
  margin-left: auto;
  box-shadow: none;
}

.status-pill::before,
.audit-pill::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
  flex-shrink: 0;
}

.status-pill>.dot,
.audit-pill>.dot {
  display: none;
}

.status-pill.success,
.audit-pill.success {
  color: #1f8a5b;
  background: #ddf4e8;
  border-color: rgba(31, 138, 91, 0.2);
}

.status-pill.warning,
.audit-pill.warning {
  color: #b46a12;
  background: #fff0d1;
  border-color: rgba(180, 106, 18, 0.22);
}

.status-pill.error,
.audit-pill.error {
  color: #b23b3b;
  background: #fce3e3;
  border-color: rgba(178, 59, 59, 0.2);
}

.status-pill.info,
.audit-pill.info {
  color: #2c6eb7;
  background: #e2effc;
  border-color: rgba(44, 110, 183, 0.22);
}

.status-columns {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 12px;
}

.status-lane {
  padding: 14px;
}

.lane-head {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 12px;
}

.lane-list {
  display: grid;
  gap: 10px;
}

.lane-card,
.history-card {
  padding: 12px;
}

.lane-card small,
.history-meta {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 8px;
  color: var(--color-text-muted);
}

.history-card strong {
  font-size: 14px;
}

.history-card p {
  margin: 8px 0;
  color: var(--color-text-main);
  font-size: 13px;
  line-height: 1.5;
}

.audit-panel {
  margin-top: 18px;
}

.audit-tabs {
  gap: 10px;
  flex-wrap: wrap;
  margin: 18px 0;
}

.audit-tab {
  min-height: 38px;
  padding: 0 14px;
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, 0.4);
  border: 1px solid var(--color-border);
  color: var(--color-text-main);
  font-size: 13px;
  font-weight: 700;
}

.audit-tab.active {
  background: var(--color-primary);
  color: #fff;
}

.audit-layout {
  align-items: stretch;
  gap: 16px;
}

.audit-table-wrap {
  flex: 1 1 68%;
  min-width: 0;
}

.nevari-admin-storefront .audit-table-wrap .table-scroll>table {
  width: max-content;
  min-width: 100%;
}

.nevari-admin-storefront .audit-table-wrap th,
.nevari-admin-storefront .audit-table-wrap td {
  white-space: nowrap;
  overflow-wrap: normal;
  word-break: normal;
  vertical-align: top;
}

.nevari-admin-storefront .audit-table-wrap .table-title {
  min-width: max-content;
}

.nevari-admin-storefront .audit-table-wrap .table-title strong,
.nevari-admin-storefront .audit-table-wrap .table-title span {
  white-space: nowrap;
}

.nevari-admin-storefront .audit-table-wrap tbody td:last-child {
  min-width: 280px;
  max-width: 420px;
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.audit-detail {
  flex: 0 0 320px;
  padding: 18px;
}

.audit-detail-empty {
  min-height: 100dvh;
  padding: 24px;
  display: grid;
  place-items: center;
  text-align: center;
  gap: 10px;
}

.audit-detail-content {
  display: grid;
  gap: 14px;
}

.detail-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.detail-block,
.meta-block {
  padding: 12px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.36);
}

.detail-block span,
.meta-block span {
  display: block;
  margin-bottom: 6px;
  color: var(--color-text-muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-weight: 700;
}

.meta-block pre {
  margin: 0;
  white-space: pre-wrap;
  word-break: break-word;
  font: 12px/1.5 ui-monospace, SFMono-Regular, Consolas, monospace;
  color: var(--color-text-main);
}

.select-wrap {
  gap: 8px;
  padding: 0 0 0 12px;
  border-radius: var(--radius-pill);
  background: rgba(255, 255, 255, 0.32);
}

.select-wrap span {
  color: var(--color-text-muted);
  font-size: 11px;
  font-weight: 700;
}

.select-wrap select {
  border: 0;
  min-height: 38px;
  padding: 0 36px 0 12px;
  border-radius: var(--radius-pill);
  outline: none;
  color: var(--color-text-main);
  appearance: none;
}

.audit-row {
  cursor: pointer;
}

.audit-row.active {
  background: rgba(231, 238, 248, 0.62);
}

.mobile-only {
  display: none;
}

.auth-gate {
  position: fixed;
  inset: 0;
  background-color: #f7f9ff;
  background-image: url("/Frame 1984078457.png");
  background-position: center bottom;
  background-size: 100% 100%;
  background-repeat: no-repeat;
  padding: 28px 16px 40px;
  z-index: 80;
  overflow-y: auto;
}

.auth-gate[hidden] {
  display: none;
}

.auth-gate-shell {
  width: min(440px, 100%);
  min-height: 100dvh;
  margin: 0 auto;
  display: grid;
  place-items: center;
  align-content: center;
  grid-auto-rows: max-content;
  gap: 16px;
}

.auth-screen-card {
  width: 100%;
  max-width: 420px;
  overflow: visible;
  padding: 0;
  border-radius: 28px;
  background: #ffffff;
  border: 1px solid rgba(10, 42, 94, 0.08);
  box-shadow: none;
  backdrop-filter: none;
  position: relative;
}

.auth-card-body {
  padding: 20px 20px 24px;
  display: flex;
  flex-direction: column;
  align-items: stretch;
}

.auth-feedback {
  font-size: 13px;
  line-height: 1.55;
  color: var(--color-text-muted);
  text-align: center;
  width: 100%;
  margin: 16px 0 0;
}

.auth-intro {
  display: grid;
  justify-items: center;
  gap: 8px;
  margin-bottom: 0;
  text-align: center;
}

.auth-logo {
  width: 86px;
  height: 86px;
  object-fit: contain;
  display: block;
}

.auth-dashboard-name {
  margin: 0;
  color: #0a2a5e;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.2;
}

.auth-title {
  margin: 0;
  color: #000000;
  font-size: clamp(28px, 4vw, 34px);
  font-weight: 400;
  line-height: 1;
  letter-spacing: -0.03em;
  text-align: left;
}

.auth-form {
  display: grid;
  gap: 14px;
  margin-top: 16px;
  width: 100%;
  max-width: none;
}

.auth-google-panel {
  display: grid;
  justify-items: center;
  gap: 12px;
  margin-top: 14px;
}

.auth-google-button-slot {
  min-height: 42px;
  display: grid;
  place-items: center;
}

.auth-google-loading {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--primary);
  font-size: 13px;
  font-weight: 700;
}

.auth-divider {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
}

.auth-divider::before,
.auth-divider::after {
  content: "";
  flex: 1;
  height: 1px;
  background: var(--color-border);
}

.form-group {
  margin: 0;
  text-align: left;
}

.auth-reference-form label>span {
  display: block;
  margin-bottom: 8px;
  color: rgba(0, 0, 0, 0.75);
  font-size: 14px;
  font-weight: 400;
  letter-spacing: -0.01em;
  text-transform: none;
}

.input-wrap {
  position: relative;
}

.input-icon {
  position: absolute;
  left: 13px;
  top: 50%;
  width: 15px;
  height: 15px;
  transform: translateY(-50%);
  color: rgba(14, 41, 85, 0.42);
  pointer-events: none;
}

.auth-reference-form input {
  width: 100%;
  height: 40px;
  padding: 0 52px 0 14px;
  border-radius: 8px;
  border: 1px solid rgba(10, 42, 94, 0.14);
  background: #f9fbff;
  color: var(--color-text-main);
  outline: none;
  transition: border-color 180ms ease, background 180ms ease;
}

.auth-reference-form input::placeholder {
  color: rgba(15, 23, 42, 0.35);
}

.auth-reference-form input:focus {
  border-color: #0a2a5e;
  background: #fff;
  box-shadow: none;
}

.input-suffix {
  position: absolute;
  right: 13px;
  top: 50%;
  transform: translateY(-50%);
  min-height: auto;
  background: transparent;
  color: var(--color-text-muted);
  font-size: 11px;
  font-weight: 600;
}

.auth-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 14px;
  justify-content: stretch;
}

.auth-primary-button,
.auth-secondary-button {
  min-height: 40px;
  border-radius: var(--radius-pill);
  padding: 0 20px;
  font-size: 13px;
  font-weight: 600;

}

.auth-primary-button {
  width: 100%;
  flex: 1 1 auto;
  min-height: 48px;
  background: #0a2a5e;
  color: #fff;
  border-radius: 999px;
  box-shadow: none;
  justify-content: center;
}

.auth-primary-button:hover {
  background: #0a2a5e;
  transform: none;
}

.auth-primary-button:disabled {
  opacity: 0.7;
  cursor: wait;
}

.auth-button-spinner {
  width: 14px;
  height: 14px;
  margin-right: 8px;
  border-radius: 50%;
  border: 2px solid rgba(255, 255, 255, 0.32);
  border-top-color: #fff;
  animation: spin 0.8s linear infinite;
  display: inline-block;
  vertical-align: -2px;
}

.auth-secondary-button {
  flex: 1 1 160px;
  background: #ffffff;
  border: 1px solid var(--color-border-strong);
  color: var(--color-text-main);
  box-shadow: none;
}

.auth-secondary-button:hover {
  background: #ffffff;
  transform: none;
}

.auth-inline-links {
  display: flex;
  justify-content: center;
  gap: 10px;
  margin-top: 2px;
  flex-wrap: wrap;
}

.auth-text-link {
  flex: 0 0 auto;
  min-height: auto;
  padding: 0;
  background: transparent;
  color: #000000;
  font-size: 13px;
  font-weight: 400;
  text-decoration: underline;
  text-decoration-color: rgba(10, 42, 94, 0.35);
  text-underline-offset: 3px;
}

.auth-text-link:disabled {
  color: rgba(0, 0, 0, 0.45);
  cursor: not-allowed;
  text-decoration-color: rgba(0, 0, 0, 0.18);
}

@media (max-width: 1240px) {

  .metrics-grid,
  .operations-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .analytics-grid,
  .dual-table-grid,
  .hero-panel,
  .mix-layout,
  .audit-layout {
    grid-template-columns: 1fr;
    display: grid;
  }

  .status-columns {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 980px) {
  body {
    padding: 16px;
  }

  .page-shell {
    grid-template-columns: 1fr;
  }

  .sidebar {
    position: fixed;
    top: 16px;
    left: 16px;
    bottom: 16px;
    width: min(320px, calc(100vw - 32px));
    min-height: auto;
    z-index: 40;
    transform: translateX(-110%);
    transition: transform 220ms ease;
  }

  .sidebar.open {
    transform: translateX(0);
  }

  .main-shell {
    padding: 16px;
  }

  .mobile-only {
    display: grid;
  }

  .topbar,
  .topbar-actions,
  .toolbar,
  .panel-header,
  .auth-actions {
    flex-wrap: wrap;
  }

  .topbar {
    grid-template-columns: 1fr;
    height: auto;
    gap: 12px;
  }

  .topbar-actions {
    justify-content: flex-start;
    width: 100%;
  }

  .search-field {
    width: 100%;
  }

  .hero-panel {
    padding: 18px;
  }

  .hero-spotlight {
    grid-template-columns: 1fr 1fr;
  }

  .spotlight-card strong {
    font-size: 28px;
  }
}

@media (max-width: 720px) {

  .metrics-grid,
  .operations-grid,
  .mini-stat-grid,
  .status-columns,
  .detail-grid {
    grid-template-columns: 1fr;
  }

  .hero-copy h1 {
    font-size: 28px;
  }

  .panel,
  .metric-card,
  .hero-panel {
    padding: 16px;
  }

  .main-shell {
    padding: 14px;
  }

  .role-topbar {
    gap: 10px;
    margin-bottom: 14px;
  }

  .role-gap,
  .role-metrics,
  .role-status-row {
    margin-top: 14px;
  }

  .role-shell .table-panel,
  .role-shell .panel {
    padding: 14px;
  }

  .role-shell .toolbar {
    align-items: stretch;
  }

  .role-shell .toolbar .pill-button {
    flex: 1 1 calc(50% - 5px);
  }

  .role-app-header {
    align-items: flex-start;
  }

  .role-overview-grid,
  .doctor-overview-grid,
  .role-doctor-strip {
    grid-template-columns: 1fr;
  }

  .role-appointment-card,
  .role-consultation-card {
    align-items: flex-start;
    flex-wrap: wrap;
  }

  .role-appointment-card em,
  .role-consultation-card em {
    margin-left: 0;
  }

  .calendar-widget {
    gap: 5px;
  }

  .calendar-day {
    border-radius: 10px;
  }

  .auth-gate {
    padding: 24px 14px 32px;
    align-items: flex-start;
  }

  .auth-screen-card {
    border-radius: 28px;
  }

  .auth-card-body {
    padding: 24px 18px 22px;
  }

  .auth-form {
    max-width: 100%;
  }

  .topbar {
    align-items: stretch;
  }

  .topbar-left,
  .topbar-actions,
  .toolbar,
  .panel-header {
    width: 100%;
  }

  .topbar-actions>* {
    flex: 1 1 calc(50% - 10px);
    min-width: 0;
  }

  .topbar-actions .icon-button {
    flex: 0 0 38px;
  }

  .user-chip {
    justify-content: flex-start;
  }

  .hero-spotlight {
    grid-template-columns: 1fr;
  }

  .bar-chart {
    min-width: 520px;
  }

  .audit-detail {
    flex-basis: auto;
  }

  table {
    min-width: 760px;
  }
}

@media (max-width: 400px) {
  .auth-gate {
    padding: 20px 12px 28px;
    background-image: url("/Frame 1984078458.png");
    background-position: center bottom;
    background-size: 100% 100%;
  }

  .auth-gate-shell {
    width: 100%;
  }

  .auth-screen-card {
    max-width: 100%;
    min-height: 0;
    border-radius: 26px;
    border-color: rgba(10, 42, 94, 0.08);
    box-shadow: none;
  }

  .auth-card-body {
    padding: 22px 16px 20px;
  }

  .auth-logo {
    width: 72px;
    height: 72px;
  }

  .auth-title {
    font-size: 28px;
    font-weight: 400;
  }

  .auth-reference-form input {
    height: 42px;
    font-size: 14px;
  }

  .auth-primary-button,
  .auth-secondary-button {
    min-height: 48px;
    font-size: 14px;
  }

}

@media (max-width: 560px) {
  body {
    padding: 12px;
  }

  .sidebar {
    top: 12px;
    left: 12px;
    bottom: 12px;
    width: min(320px, calc(100vw - 24px));
  }

  .main-shell {
    border-radius: 24px;
    padding: 12px;
  }

  .topbar-actions>* {
    flex: 1 1 100%;
  }

  .topbar-actions .icon-button {
    flex: 0 0 38px;
  }

  .metrics-grid,
  .analytics-grid,
  .dual-table-grid,
  .operations-grid {
    gap: 14px;
  }

  .hero-copy h1 {
    font-size: 24px;
  }

  .hero-text {
    font-size: 13px;
  }
}

.brand-logo-shell {
  overflow: hidden;
  background: rgba(255, 255, 255, 0.82);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.75), 0 12px 28px rgba(14, 41, 85, 0.12);
}

.brand-logo {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.pill-button:disabled,
.icon-button:disabled,
.button-primary:disabled {
  opacity: 0.65;
  cursor: wait;
}

.overview-hero {
  background:
    radial-gradient(circle at top right, rgba(216, 202, 182, 0.42), transparent 32%),
    linear-gradient(135deg, rgba(255, 253, 248, 0.98), rgba(231, 238, 248, 0.9));
}

.spotlight-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.overview-grid {
  display: grid;
  grid-template-columns: 1.05fr 0.95fr 0.95fr;
  gap: 18px;
  margin-bottom: 18px;
}

.overview-grid-secondary {
  grid-template-columns: 1.2fr 0.8fr;
}

.priority-list,
.signal-list,
.settings-grid {
