/* Dashboard layout polish */
:root {
  --space-page: clamp(12px, 1.8vw, 24px);
  --space-shell: clamp(12px, 1.4vw, 18px);
  --space-panel: clamp(16px, 1.5vw, 20px);
  --radius-xs: 8px;
  --radius-sm: 8px;
  --radius-md: 8px;
  --radius-lg: 8px;
  --radius-xl: 8px;
}

html {
  height: 100%;
  min-width: 320px;
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
  overflow: hidden;
}

body {
  height: 100%;
  overflow: hidden;
  padding: var(--space-page);
  font-size: 14px;
  line-height: 1.5;
}

h1,
h2,
h3,
p {
  overflow-wrap: anywhere;
}

.page-shell {
  gap: var(--space-shell);
  align-items: flex-start;
  height: calc(100dvh - (var(--space-page) * 2));
  overflow: hidden;
}

.sidebar {
  top: var(--space-page);
  min-height: calc(100dvh - (var(--space-page) * 2));
  padding: 18px 16px;
}

@media (min-width: 981px) {
  .sidebar {
    position: fixed;
    top: var(--space-page);
    left: max(var(--space-page), calc((100vw - 1480px) / 2 + var(--space-page)));
    width: var(--sidebar-width);
    height: calc(100dvh - (var(--space-page) * 2));
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-gutter: stable;
  }

  .main-shell {
    grid-column: 2;
    height: calc(100dvh - (var(--space-page) * 2));
    overflow: hidden;
    display: flex;
    flex-direction: column;
  }

  .topbar {
    position: relative;
    top: auto;
    flex: 0 0 auto;
  }

  .pages-stack {
    flex: 1 1 auto;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    padding-right: 2px;
    overscroll-behavior: contain;
  }
}

.main-shell {
  min-width: 0;
  padding: var(--space-shell);
  height: -webkit-fill-available;
}

.pages-stack,
.page-view.active {
  min-width: 0;
}

.topbar {
  align-items: flex-start;
  gap: 12px;
  margin-bottom: var(--space-shell);
  position: sticky;
  top: 0;
  z-index: 60;
  margin: calc(var(--space-shell) * -1) calc(var(--space-shell) * -1) var(--space-shell);
  padding: var(--space-shell);
  background: linear-gradient(180deg, rgba(248, 245, 239, 0.98), rgba(248, 245, 239, 0.94));
  border-radius: var(--radius-xl) var(--radius-xl) 0 0;

  backdrop-filter: blur(14px);
}

@media (min-width: 981px) {
  .page-shell {
    height: calc(100dvh - (var(--space-page) * 2));
    overflow: hidden;
  }

  .sidebar {
    position: fixed;
    top: var(--space-page);
    left: max(var(--space-page), calc((100vw - 1480px) / 2 + var(--space-page)));
    width: var(--sidebar-width);
    height: calc(100dvh - (var(--space-page) * 2));
    min-height: 0;
    overflow-y: auto;
    overscroll-behavior: contain;
    scrollbar-gutter: stable;
  }

  .main-shell {
    grid-column: 2;
    height: calc(100dvh - (var(--space-page) * 2));
    min-height: 0;
    overflow: hidden;
    display: flex;
    flex-direction: column;
  }

  .topbar {
    flex: 0 0 auto;
    flex-shrink: 0;
    position: sticky;
    top: 0;
  }

  .pages-stack {
    flex: 1 1 auto;
    min-height: 0;
