.chart-scroll {
  width: 100%;
  overflow-x: auto;
  padding-bottom: 4px;
}

.bar-fill {
  transition: height 420ms ease, background-color 280ms ease, opacity 280ms ease;
}

.bar-fill.placeholder {
  opacity: 0.4;
}

.bar-note {
  display: grid;
  gap: 4px;
}

.bar-note small {
  color: var(--color-text-muted);
  font-size: 11px;
}

.donut-chart {
  position: relative;
  overflow: hidden;
  background: radial-gradient(circle, rgba(248, 245, 239, 0.96) 0 42%, transparent 43%);
}

.donut-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  transform: rotate(-90deg);
}

.donut-track,
.donut-segment {
  fill: none;
  stroke-width: 24;
}

.donut-track {
  stroke: rgba(14, 41, 85, 0.08);
}

.donut-segment {
  stroke-linecap: butt;
  transition: stroke-dasharray 420ms ease, stroke-dashoffset 420ms ease;
}

.donut-segment.teal {
  stroke: var(--color-accent-teal);
}

.donut-segment.rose {
  stroke: var(--color-accent-rose);
}

.donut-segment.lime {
  stroke: #dac8ad;
}

.donut-segment.violet {
  stroke: #64799d;
}

.donut-center {
  position: relative;
  z-index: 1;
}

