  text-overflow: ellipsis;
}


.doctor-result-info {
  min-width: 0;
  flex: 1;
}

.doctor-result-name {
  display: block;
  font-size: 13px;
  font-weight: 800;
  color: #142f52;
  margin-bottom: 4px;
