}

.doctor-result-meta {
  display: block;
  font-size: 11px;
  color: #6f7f93;
  line-height: 1.25;
}

.doctor-assign-btn {
  flex-shrink: 0;
  padding: 8px 14px;
  border-radius: 999px;
  margin-right: 2px;
}

.doctor-search-results .compact-empty {
  margin: 0;
  padding: 12px 14px;
  border-radius: 12px;
  box-shadow: none;
}

.product-category-doctor-strip-card .doctor-search-wrapper {
  position: relative;
}

.product-category-doctor-strip-card .doctor-search-results {
  position: absolute;
  top: calc(100% + 8px);
  left: 0;
  right: 0;
  z-index: 9999;
}

.product-category-price-suffix {
  font-weight: 400;
}

.category-saving-spinner {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  border: 2px solid rgba(14, 41, 85, 0.15);
  border-top-color: var(--color-text-main);
  animation: spin 0.8s linear infinite;
  flex: 0 0 auto;
}

.product-category-product-card {
  min-height: 72px;
  padding: 10px 14px 10px 12px;
  border-radius: 18px;
