  grid-template-columns: 48px minmax(0, 1fr) auto 26px;
  gap: 14px;
  align-items: center;
  box-shadow: none;
}

.product-category-product-remove {
  position: static;
  order: 4;
  width: 26px;
  min-height: 26px;
  padding: 0;
  border-radius: 999px;
  background: transparent;
  display: grid;
  place-items: center;
  color: var(--color-text-muted);
}

.product-category-product-remove svg {
  width: 16px;
  height: 16px;
  stroke-width: 2.4;
}

.product-category-product-card .product-thumb {
  order: 1;
  width: 48px;
  height: 48px;
  border-radius: 14px;
  background: #eef4fb;
}

.product-category-product-card .table-title {
  order: 2;
  min-width: 0;
}

.product-category-product-card .table-title strong {
  color: var(--color-primary);
  font-size: 13px;
  line-height: 1.15;
}

.product-category-product-card .table-title span {
  margin-top: 4px;
  color: #687891;
  font-size: 11px;
  font-weight: 700;
}

.product-category-product-card .status-pill {
  order: 3;
  min-height: 30px;
  min-width: 74px;
  justify-content: center;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 800;
}

.product-category-inline-head {
  align-items: end;
}

.product-category-inline-group {
  display: grid;
  gap: 6px;
  min-width: 0;
  align-self: anchor-center;
}

.product-category-inline-trigger {
  min-height: 0;
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--color-text-main);
  display: inline-flex;
  align-items: center;
  gap: 8px;
  text-align: left;
}

.product-category-inline-trigger svg {
  width: 16px;
  height: 16px;
  color: var(--color-text-muted);
}

.product-category-name-trigger strong,
.product-category-name-input {
  font-size: 28px;
  font-weight: 700;
  line-height: 1.08;
}

.product-category-price-trigger {
  justify-content: flex-end;
}

.product-category-price-trigger strong,
.product-category-price-input,
.product-category-currency {
  font-size: 18px;
  font-weight: 700;
}

.product-category-inline-input {
  width: 100%;
  min-width: 0;
  min-height: 0;
  padding: 0;
  border: 0;
  border-bottom: 1px solid rgba(14, 41, 85, 0.18);
  border-radius: 0;
  background: transparent;
  color: var(--color-text-main);
  outline: none;
}

.product-category-name-editor {
  display: flex;
  align-items: center;
  gap: 10px;
}

.product-category-price-editor {
  display: inline-flex;
  align-items: baseline;
  gap: 6px;
  justify-content: flex-end;
}

.product-category-price-input {
  width: 112px;
  text-align: right;
}

.product-category-currency,
.product-category-save-notice {
  color: var(--color-text-muted);
}

.product-category-save-notice {
  text-align: right;
  font-size: 11px;
}

.product-category-products-header {
  padding: 0;
}

.products-bulk-bar {
  margin-bottom: 14px;
  padding: 10px 12px;
  border-radius: 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  flex-wrap: wrap;
  background: rgba(255, 255, 255, 0.34);
  border: 1px solid var(--color-border);
  box-shadow: var(--shadow-inset);
}

.products-bulk-delete {
  min-height: 36px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0 16px;
  border-radius: var(--radius-pill);
  background: #b42318;
  color: #fff;
  font-size: 12px;
  font-weight: 700;
  box-shadow: 0 10px 20px rgba(180, 35, 24, 0.18);
}

.products-bulk-delete:hover {
  background: #912018;
}

.products-table th,
.products-table td {
  white-space: nowrap;
}

.products-table th:first-child,
.products-table td:first-child {
  width: 46px;
}

.products-table .image-col {
  width: 52px;
}

.products-table .sku-col {
  width: 156px;
  min-width: 156px;
  max-width: 180px;
  white-space: normal;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.products-table .price-col {
  width: 96px;
  max-width: 96px;
}

.products-table .featured-col {
  width: 44px;
  max-width: 44px;
}

.bulk-check-col,
.image-col,
.featured-col {
  text-align: center;
}

.bulk-check {
  width: 20px;
  height: 20px;
  margin: 0;
  accent-color: var(--color-primary);
}

.product-row:hover {
  background: rgba(231, 238, 248, 0.34);
}

.product-row {
  opacity: 1;
  transform: translateX(0);
  transition: opacity 220ms ease, transform 220ms ease, background 160ms ease;
}

.product-row-deleting {
  opacity: 0;
  transform: translateX(-24px);
  pointer-events: none;
}

.product-row-draft {
  color: var(--color-text-muted);
}

.product-row-draft:hover {
  background: rgba(14, 41, 85, 0.04);
}

.product-row-draft .product-thumb {
  background: rgba(14, 41, 85, 0.08);
  color: rgba(14, 41, 85, 0.42);
  filter: grayscale(1);
}

.product-row-draft .product-thumb img {
  filter: grayscale(1) saturate(0.72);
}

.product-row-draft .table-link,
.product-row-draft .table-title strong,
.product-row-draft .featured-toggle,
.product-row-draft td {
  color: #7e8796;
}

.product-row-draft .muted,
.product-row-draft .table-title span,
.product-row-draft .row-actions a,
.product-row-draft .row-actions button {
  color: #97a0ae;
}

.product-row-draft .stock-label.instock,
.product-row-draft .stock-label.outofstock,
.product-row-draft .stock-label.onbackorder,
.product-row-draft .featured-toggle.active {
  color: #7e8796;
}

.product-row-skeleton:hover {
  background: transparent;
}

.product-row-skeleton .product-thumb {
  background: transparent;
}

.product-row-skeleton .product-thumb>.skeleton {
  width: 100%;
  height: 100%;
  border-radius: inherit;
}

.product-name-cell {
  min-width: 220px;
  white-space: normal;
}

.product-name-wrap {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.row-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0;
  opacity: 0;
  transform: translateY(-2px);
  pointer-events: none;
  transition: opacity 160ms ease, transform 160ms ease;
}

.product-row:hover .row-actions,
.product-row:focus-within .row-actions {
  opacity: 1;
  transform: translateY(0);
  pointer-events: auto;
}

@media (max-width: 980px) {
  .product-categories-pane {
    grid-template-columns: 1fr;
  }

  .product-categories-content {
    padding-left: 0;
    border-left: 0;
  }

  .product-category-create-grid {
    grid-template-columns: 1fr;
  }

  .product-category-inline-head,
  .product-category-price-trigger,
  .product-category-price-editor {
    justify-content: flex-start;
  }

  .products-segmented-bar {
    margin-left: 0;
    width: 100%;
  }

  .product-category-row,
  .product-category-add-row,
  .product-category-product-card {
    flex-direction: column;
    align-items: flex-start;
  }

  .product-category-row-price,
  .product-category-price-chip {
    text-align: left;
  }
}

.row-actions a,
.row-actions button {
  padding: 0;
  background: transparent;
  color: var(--color-primary);
  font-size: 11px;
  font-weight: 700;
}

.row-actions a:hover,
.row-actions button:hover {
  color: var(--color-primary-hover);
}

.row-actions a[aria-disabled="true"],
.row-actions button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

.row-actions .row-action-trash,
.row-actions .row-action-trash:hover {
  color: #c62828;
}

.row-actions>*:not(:last-child)::after {
  content: "|";
  margin: 0 6px;
  color: rgba(14, 41, 85, 0.28);
}

.stock-label {
  font-size: 14px;
}

.stock-label.instock {
  color: #0a8f2f;
}

.stock-label.outofstock,
.stock-label.onbackorder {
  color: #b42318;
}

.featured-toggle {
  width: 30px;
  height: 30px;
  display: inline-grid;
  place-items: center;
  border-radius: 999px;
  background: transparent;
  color: #8aa1c4;
  font-size: 22px;
  line-height: 1;
}

.featured-toggle.active {
  color: #f4b400;
}

.product-editor-modal {
  width: min(1400px, 95vw);
  height: min(92vh, 920px);
  max-height: calc(100vh - 32px);
  padding: 0;
  overflow: hidden;
  border-radius: 32px;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.985), rgba(248, 245, 239, 0.985)),
    var(--color-bg-card);
  box-shadow: 0 28px 72px rgba(14, 41, 85, 0.22);
  opacity: 1;
  transform: translateX(0);
  transition: opacity 220ms ease, transform 220ms ease;
}

.product-editor-modal-deleting {
  opacity: 0;
  transform: translateX(-24px);
  pointer-events: none;
}

.product-editor-form {
  display: grid;
  height: 100%;
  grid-template-rows: auto minmax(0, 1fr) auto;
}

.product-editor-header {
  padding: 28px 32px 20px;
}

.product-editor-shell {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  grid-template-columns: 65% 30%;
  gap: 18px;
  overflow: hidden;
  padding: 0 20px 18px;
}

.product-editor-media-column {
  min-width: 0;
  overflow: hidden;
}

.product-editor-form-column {
  min-width: 0;
  display: grid;
  grid-template-rows: minmax(0, 1fr);
  overflow: hidden;
}

.product-editor-panel {
  background: #faf9f7;
  border: 1px solid #ececec;
  box-shadow: none;
}

.product-media-panel {
  height: 100%;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 14px;
  padding: 16px;
  border-radius: 22px;
}

.product-editor-panel-header {
  margin-bottom: 0;
}

.product-thumbnail img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.product-media-empty {
  grid-column: 1 / -1;
  min-height: 108px;
  display: grid;
  place-items: center;
  gap: 10px;
  color: var(--color-text-muted);
  border-radius: 14px;
  border: 1px dashed rgba(121, 141, 176, 0.42);
}

.product-thumbnail-grid {
  flex: 1 1 auto;
  min-height: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, var(--product-thumb-min, 88px)), 1fr));
  grid-auto-rows: minmax(0, 1fr);
  align-content: start;
  gap: 10px;
  overflow: hidden;
}

.product-thumbnail {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  padding: 0;
  border-radius: 12px;
  overflow: hidden;
  border: 1.5px solid rgba(14, 41, 85, 0.08);
  background: rgba(255, 255, 255, 0.96);
  box-shadow: none;
  transition: transform 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
}

.product-thumbnail-surface {
  width: 100%;
  height: 100%;
  padding: 0;
  border: 0;
  background: transparent;
}

.product-thumbnail-index {
  position: absolute;
  z-index: 1;
  top: 6px;
  left: 6px;
  min-width: 22px;
  height: 22px;
  padding: 0 6px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: rgba(14, 41, 85, 0.88);
  color: #fff;
  font-size: 11px;
  font-weight: 700;
}

.product-thumbnail:hover,
.product-thumbnail.active {
  transform: translateY(-1px);
  border-color: var(--color-primary);
  box-shadow: 0 0 0 1px var(--color-primary);
}

.product-thumbnail-edit {
  position: absolute;
  top: 8px;
  right: 8px;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.96);
  color: var(--color-primary);
  box-shadow: var(--shadow-card);
  opacity: 0;
  transition: opacity 160ms ease, transform 160ms ease;
}

.product-thumbnail-remove {
  position: absolute;
  right: 8px;
  bottom: 8px;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.96);
  color: #c62828;
  box-shadow: var(--shadow-card);
  opacity: 0;
  transition: opacity 160ms ease, transform 160ms ease;
}

.product-thumbnail:hover .product-thumbnail-edit,
.product-thumbnail:hover .product-thumbnail-remove,
.product-thumbnail:focus-within .product-thumbnail-edit,
.product-thumbnail:focus-within .product-thumbnail-remove {
  opacity: 1;
}

.product-thumbnail-edit:hover,
.product-thumbnail-remove:hover {
  transform: translateY(-1px);
}

.product-upload-dropzone {
  min-height: 64px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  border-radius: 14px;
  border: 1.5px dashed rgba(121, 141, 176, 0.52);
  background: rgba(255, 255, 255, 0.54);
  color: var(--color-primary);
  text-align: left;
}

.product-upload-dropzone:disabled,
.product-status-toggle:disabled,
.product-editor-tab:disabled {
  cursor: not-allowed;
  opacity: 0.58;
}

.product-upload-dropzone-icon {
