.skeleton {
  position: relative;
  overflow: hidden;
  background: rgba(14, 41, 85, 0.11);
}

.skeleton::after {
  content: "";
  position: absolute;
  inset: 0;
  transform: translateX(-100%);
  background: linear-gradient(
    100deg,
    transparent 8%,
    rgba(255, 255, 255, 0.24) 30%,
    rgba(255, 255, 255, 0.92) 50%,
    rgba(255, 255, 255, 0.24) 70%,
    transparent 92%
  );
  animation: nevari-shimmer 1.35s linear infinite;
}

@keyframes nevari-shimmer {
  100% {
    transform: translateX(100%);
  }
}

