}

.dashboard-swr-reveal.is-active {
  animation: dashboardSWRFadeInDown 260ms cubic-bezier(0.22, 1, 0.36, 1);
  transform-origin: top center;
}

@media (prefers-reduced-motion: reduce) {
  .dashboard-swr-reveal.is-active {
    animation: none;
  }
}

