  max-width: 100%;
  margin: 0 auto;
  padding: 14px;
  background: #f8fafc;
}

.customer-appointment-checkout-summary-head {
  display: grid;
  grid-template-columns: 42px minmax(0, 1fr) auto;
  gap: 12px;
  align-items: center;
  text-align: left;
}

.customer-appointment-checkout-row-icon {
  width: 42px;
  height: 42px;
  border-radius: 999px;
  background: #e8f5ee;
  color: #2f9461;
  display: grid;
  place-items: center;
}

.customer-appointment-checkout-summary-copy {
  display: grid;
  gap: 2px;
}

.customer-appointment-checkout-summary-copy span,
.customer-appointment-checkout-meta span {
  color: #526078;
  font-size: 12px;
}

.customer-appointment-checkout-summary-copy strong,
.customer-appointment-checkout-meta strong {
  color: #0b326d;
  font-size: 15px;
  font-weight: 600;
}

.customer-appointment-checkout-summary-head em,
.customer-appointment-confirmation-head .badge {
  padding: 6px 10px;
  border-radius: 999px;
  background: #e8f5ee;
  color: #2f9461;
  font-weight: 600;
  font-size: 12px;
  font-style: normal;
}

.customer-appointment-checkout-summary-head em.is-warning {
  background: #fff4d6;
  color: #b7791f;
}

.customer-appointment-checkout-summary-head em.is-error {
  background: #fee7e7;
  color: #c53030;
}

.customer-appointment-checkout-meta {
  margin-top: 12px;
  display: grid;
  gap: 8px;
}

.customer-appointment-checkout-meta div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding-top: 8px;
  border-top: 1px solid #dfe4ec;
}

.customer-appointment-checkout-note {
  max-width: 320px;
  color: #526078;
  font-size: 13px;
}

.customer-appointment-checkout-error {
  width: 100%;
  max-width: 100%;
  margin: 0 auto;
  border-radius: 14px;
  background: #fee7e7;
  color: #9f1c1c;
  padding: 10px 12px;
  font-size: 14px;
}

.customer-appointment-confirmation-actions {
  width: 100%;
  max-width: 100%;
  margin: 0 auto;
  display: grid;
  gap: 10px;
}

.customer-appointment-confirmation-link {
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

.customer-appointment-confirmation-secure {
  width: 100%;
  margin: 2px 0 0;
  padding: 14px 0 0;
  border-top: 1px solid #dfe4ec;
  display: flex;
  align-items: center;
  gap: 12px;
  text-align: left;
}

.customer-appointment-confirmation-secure span {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  border-radius: 999px;
  border: 2px solid #38a169;
  position: relative;
}

.customer-appointment-confirmation-secure span::before {
  content: "";
  position: absolute;
  inset: 9px 10px 8px;
  border: 2px solid #38a169;
  border-top: 0;
  border-left: 0;
  transform: rotate(45deg);
}

.customer-appointment-confirmation-secure p {
  margin: 0;
  color: #526078;
  font-size: 13px;
  line-height: 1.45;
}

.customer-appointment-confirmation-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  color: #526078;
  font-size: 12px;
}

.customer-appointment-confirmation-summary .customer-confirmation-next-row {
  padding-top: 10px;
  font-size: 12px;
}

.customer-appointment-confirmation-summary .customer-confirmation-next-row strong {
  font-size: 14px;
  font-weight: 600;
}

.customer-flow-status-page {
  min-height: 100dvh;

  display: grid;
  place-items: center;
  background: #f3f5f9;
}

.customer-flow-status-page-success {
  background:
    radial-gradient(circle at 50% 0%, rgba(12, 50, 112, 0.06), transparent 34%),
    #f3f5f9;
}

.customer-flow-status-page-warning {
  background:
    radial-gradient(circle at 50% 0%, rgba(182, 138, 43, 0.08), transparent 34%),
    #f3f5f9;
}

.customer-flow-status-page-error {
  background:
    radial-gradient(circle at 50% 0%, rgba(197, 48, 48, 0.08), transparent 34%),
    #f3f5f9;
}

.customer-flow-status-card {
  width: min(100%, 760px);
  display: grid;
  gap: 18px;
  padding: clamp(24px, 4vw, 34px);
  border-radius: 28px;
  border: 1px solid #e5e7eb;
  background: #ffffff;
  box-shadow: 0 18px 42px rgba(15, 35, 80, 0.08);
}

.customer-flow-status-card-checkout {
  position: relative;
}

.customer-flow-status-card-checkout {
  max-width: 560px;
  gap: 22px;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  font-family: "Product Sans", "Google Sans", Arial, sans-serif;
}

.customer-flow-status-card-checkout .customer-flow-status-head {
  gap: 10px;
}

.customer-flow-status-card-checkout .customer-flow-status-head h2 {
  font-size: 24px;
  font-weight: 300;
  line-height: 1.18;
  letter-spacing: -0.025em;
}

.customer-flow-status-card-checkout .customer-flow-status-head p {
  font-size: 16px;
}

.customer-flow-status-card-checkout .customer-flow-status-icon {
  border: 0;
  box-shadow: none;
}

.customer-reservation-countdown {
  display: grid;
  justify-items: center;
  gap: 2px;
  color: #09255a;
}

.customer-reservation-countdown strong {
  font-size: 24px;
  font-weight: 300;
  font-variant-numeric: tabular-nums;
  letter-spacing: .02em;
}

.customer-flow-status-card-checkout .customer-flow-amount-card {
  border: 0;
  border-radius: 20px;
  background: #e2effc;
}

.customer-flow-status-card-checkout .customer-flow-status-panel {
  border: 0;
  border-radius: 0;
  background: #e2effc;
  padding: 0;
}

.customer-flow-status-card-checkout .customer-flow-status-actions {
  gap: 12px;
}

.customer-flow-status-card-checkout .customer-flow-status-actions :is(.customer-mobile-primary-button, .customer-mobile-secondary-button) {
  min-height: 52px;
  border-radius: 999px;
  box-shadow: none;
  font-family: "Product Sans", "Google Sans", Arial, sans-serif;
  font-size: 14px;
  font-weight: 300;
}

.customer-flow-status-card-checkout .customer-flow-status-danger-button {
  border-color: #e9b9b9;
}

.customer-flow-status-card-checkout .customer-flow-status-icon.is-warning,
.customer-flow-status-card-checkout .customer-flow-status-pill.is-processing {
  background: #e2effc;
  color: #0c3270;
}

.customer-flow-status-card-checkout .customer-flow-status-pill.is-processing {
  border-color: #0c3270;
}

.customer-flow-status-card-checkout .customer-flow-amount-value {
  font-size: clamp(24px, 7vw, 30px);
  white-space: nowrap;
}

.customer-flow-status-page-warning {
  background: #ffffff;
}

.customer-flow-status-card-confirmed {
  width: min(100%, 500px);
  max-width: 500px;
}

.customer-flow-status-card-mtm {
  width: min(100%, 520px);
}

.customer-flow-status-head {
  display: grid;
  justify-items: center;
  gap: 12px;
  text-align: center;
}

.customer-flow-status-head h2 {
  margin: 0;
  max-width: 560px;
  color: #09255a;
  font-size: clamp(28px, 4vw, 36px);
  line-height: 1.06;
  letter-spacing: -0.045em;
}

.customer-flow-status-head p {
  margin: 0;
  max-width: 580px;
  color: #7d8492;
  font-size: 15px;
  line-height: 1.6;
}

.customer-flow-status-icon {
  width: 74px;
  height: 74px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  border: 1px solid #dde2ea;
  background: #eff6ff;
  color: #0c3270;
}

.customer-flow-status-icon svg {
  width: 32px;
  height: 32px;
}

.customer-flow-status-icon.is-success {
  background: #edf8f1;
  color: #1f8a5b;
}

.customer-flow-status-icon.is-warning {
  background: #fff7e2;
  color: #b46a12;
}

.customer-flow-status-icon.is-error {
  background: #fcebec;
  color: #c53030;
}

.customer-flow-status-back {
  position: absolute;
  top: 18px;
  left: 18px;
  width: 42px;
  height: 42px;
  border: 1px solid #dde2ea;
  border-radius: 14px;
  background: #f7f8fa;
  color: #0c3270;
  display: grid;
  place-items: center;
  cursor: pointer;
}

.customer-flow-status-panel,
.customer-flow-amount-card,
.customer-flow-status-note,
.customer-flow-status-alert,
.customer-flow-security-note {
  border-radius: 24px;
}

.customer-flow-status-panel {
  border: 1px solid #dde2ea;
  background: #ffffff;
  padding: 18px;
  display: grid;
  gap: 16px;
}

.customer-flow-status-panel-soft {
  background: #f8fafc;
}

.customer-flow-status-panel-accent {
  background: #f6f9fd;
}

.customer-flow-status-panel-head {
  display: grid;
  grid-template-columns: auto 1fr auto;
  gap: 12px;
  align-items: center;
}

.customer-flow-status-panel-head-mtm {
  align-items: flex-start;
}

.customer-flow-status-panel-icon {
  width: 44px;
  height: 44px;
  border-radius: 999px;
  background: #ffffff;
  border: 1px solid #dde2ea;
  color: #0c3270;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
}

.customer-flow-status-panel-icon svg {
  width: 20px;
  height: 20px;
}

.customer-flow-status-panel-icon.is-success {
  color: #1f8a5b;
}

.customer-flow-status-panel-copy {
  display: grid;
  gap: 3px;
  text-align: left;
}

.customer-flow-status-panel-copy span {
  color: #7d8492;
  font-size: 12px;
  font-weight: 700;
}

.customer-flow-status-panel-copy strong {
  color: #09255a;
  font-size: 16px;
  line-height: 1.35;
  letter-spacing: -0.02em;
}

.customer-flow-status-pill {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 32px;
  padding: 0 14px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 750;
  white-space: nowrap;
  background: #eef2f7;
  color: #5d6675;
  border: 1px solid transparent;
}

.customer-flow-status-pill.is-success {
  background: #edf8f1;
  color: #1f8a5b;
}

.customer-flow-status-pill.is-complete {
  background: #edf8f1;
  color: #1f8a5b;
}

.customer-flow-status-pill.is-processing {
  background: #e2effc;
  color: #2c6eb7;
}

.customer-flow-status-pill.is-warning {
  background: #fff3da;
  color: #b46a12;
}

.customer-flow-status-pill.is-error {
  background: #fcebec;
  color: #c53030;
}

.customer-flow-status-pill.is-info {
  background: #eef4ff;
  color: #0c3270;
}

.customer-flow-kv-list {
  display: grid;
  gap: 0;
}

.customer-flow-kv-row {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding-top: 12px;
  margin-top: 12px;
  border-top: 1px solid #dde2ea;
}

.customer-flow-kv-row:first-child {
  margin-top: 0;
  padding-top: 0;
  border-top: 0;
}

.customer-flow-kv-key {
  color: #7d8492;
  font-size: 13px;
}

.customer-flow-kv-value {
  color: #09255a;
  font-size: 14px;
  font-weight: 700;
  text-align: right;
}

.customer-flow-amount-card {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px;
  border: 1px solid #dde2ea;
  background: #fffaf0;
}

.customer-flow-amount-label {
  display: block;
  color: #7d8492;
  font-size: 12px;
  font-weight: 700;
}

.customer-flow-amount-value {
  display: block;
  margin-top: 6px;
  color: #09255a;
  font-size: clamp(26px, 4vw, 34px);
  line-height: 1;
  letter-spacing: -0.04em;
}

.customer-flow-status-note {
  border: 1px solid #dde2ea;
  background: #fafbfd;
  padding: 14px 16px;
}

.customer-flow-status-note.is-warning {
  background: #fffaf0;
}

.customer-flow-status-note p {
  margin: 0;
  color: #5d6675;
  font-size: 14px;
  line-height: 1.55;
}

.customer-flow-status-note strong {
  color: #09255a;
}

.customer-flow-status-alert {
  border: 1px solid rgba(197, 48, 48, 0.18);
  background: #fef1f1;
  padding: 14px 16px;
}

.customer-flow-status-alert p {
  margin: 0;
  color: #9f1c1c;
  font-size: 14px;
  line-height: 1.55;
}

.customer-flow-status-actions {
  display: grid;
  gap: 2px;
}

.customer-flow-status-card-confirmed .customer-flow-status-actions {
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.customer-flow-status-actions .customer-mobile-primary-button,
.customer-flow-status-actions .customer-mobile-secondary-button,
.customer-flow-status-link {
  width: 100%;
  min-height: 50px;
  border-radius: 999px;
  justify-content: center;
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
}

.customer-flow-status-danger-button {
  border-color: rgba(178, 59, 59, 0.32);
  background: #ffffff;
  color: #b23b3b;
}

.customer-flow-security-note {
  border: 1px solid #dde2ea;
  background: #f9fbfd;
  padding: 14px 16px;
  display: flex;
  gap: 12px;
  align-items: flex-start;
}

.customer-flow-security-note.is-warning {
  background: #fffaf0;
}

.customer-flow-security-mark {
  width: 34px;
  height: 34px;
  flex: 0 0 34px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background: #ffffff;
  color: #1f8a5b;
  border: 1px solid rgba(31, 138, 91, 0.12);
}

.customer-flow-security-mark svg {
  width: 18px;
  height: 18px;
}

.customer-flow-security-note.is-warning .customer-flow-security-mark {
  color: #b46a12;
  border-color: rgba(180, 106, 18, 0.18);
}

.customer-flow-security-note p {
  margin: 0;
  color: #5d6675;
  font-size: 13px;
  line-height: 1.5;
  text-align: left;
}

.customer-mobile-primary-button:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

@media (min-width: 768px) {
  .customer-flow-status-card {
    gap: 22px;
    padding: 34px;
  }

  .customer-flow-status-actions {
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  }

  .customer-flow-status-card-confirmed .customer-flow-status-actions {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
}

@media (max-width: 540px) {
  .customer-flow-status-card {
    border-radius: 24px;
    padding: 22px 16px 18px;
    gap: 16px;
  }

  .customer-flow-status-back {
    top: 14px;
    left: 14px;
  }

  .customer-flow-status-head h2 {
    font-size: 28px;
  }

  .customer-flow-status-panel-head,
  .customer-flow-amount-card,
  .customer-flow-kv-row {

    display: flex;
    justify-content: space-between;
  }

  .customer-flow-kv-value,
  .customer-flow-status-pill {
    text-align: left;
    justify-self: start;
  }
}

@keyframes customerMobileFadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }

  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes customerMobileFadeOut {
  from {
    opacity: 1;
    transform: translateY(0);
  }

  to {
    opacity: 0;
    transform: translateY(-4px);
  }
}

@keyframes customerMobilePageSlideFadeIn {
  from {
    opacity: 0;
    transform: translateX(14px);
  }

  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes customerMobilePageSearchFadeZoomIn {
  from {
    opacity: 0;
    transform: scale(0.975);
  }

  to {
    opacity: 1;
    transform: scale(1);
  }
}

.customer-mobile-drawer-layer.open {
