  background: #ffffff;
  padding: 28px 22px 20px;
  display: flex;
  flex-direction: column;
}

.customer-mobile-drawer-brand {
  width: 100%;
  height: auto;
  margin-bottom: 24px;
}

.customer-mobile-drawer-brand img {
