    grid-template-columns: 1fr;
  }
}

.subscription-shell {
  min-height: 100dvh;
  max-width: 430px;
  margin: 0 auto;
  padding: 0.9rem 1.25rem calc(env(safe-area-inset-bottom, 0px) + 1.2rem);
  gap: 1.2rem;
  background:
    radial-gradient(circle at 50% 100%, rgba(242, 205, 116, 0.09), transparent 34%),
    linear-gradient(180deg, #ffffff 0%, #fffdf9 100%);
}

.subscription-shell-success {
  justify-content: space-between;
}

.subscription-shell-loading {
  justify-content: center;
  align-items: center;
}

.subscription-loading-card {
  width: 100%;
  border-radius: 28px;
  padding: 1.4rem 1.2rem;
  background: linear-gradient(180deg, #ffffff 0%, #f7f8fb 100%);
  border: 1px solid rgba(6, 38, 95, 0.08);
  box-shadow: 0 18px 40px rgba(10, 34, 82, 0.08);
}

.subscription-loading-spinner {
  width: 48px;
  height: 48px;
  border-radius: 999px;
  border: 4px solid rgba(11, 50, 109, 0.16);
  border-top-color: #0b326d;
  animation: subscription-spinner-rotate 0.8s linear infinite;
}

.subscription-menu-button {
  width: 2.2rem;
  height: 2.2rem;
  padding: 0.35rem 0.25rem;
  align-self: flex-start;
}

.subscription-menu-button span {
  width: 0.95rem;
