/* Shared modal system */
:root {
  --modal-overlay: rgba(6, 27, 63, 0.42);
  --modal-overlay-soft: rgba(6, 27, 63, 0.34);
  --modal-surface: #fbf8f3;
  --modal-border: rgba(255, 255, 255, 0.72);
  --modal-shadow: 0 28px 70px rgba(7, 15, 32, 0.22);
  --modal-radius: 30px;
  --modal-header-border: rgba(14, 41, 85, 0.10);
}

:where(.app-modal-backdrop, .subscription-modal-backdrop, .customer-confirmation-modal, .customer-appointment-modal-backdrop, .customer-mobile-drawer-backdrop, .dashboard-side-nav-backdrop) {
  background: var(--modal-overlay);
  backdrop-filter: blur(10px);
}

.subscription-modal-backdrop,
.customer-confirmation-modal {
  isolation: isolate;
}

.subscription-modal-frame,
.category-create-popup,
.stacked-order-popup,
.product-editor-modal,
.order-modal,
.customer-confirmation-modal .customer-confirmation-shell,
.customer-appointment-detail-card,
.customer-mobile-drawer,
.dashboard-side-nav {
  border-radius: var(--modal-radius);
  border: 1px solid var(--modal-border);
  box-shadow: var(--modal-shadow);
  background-color: #ffffff !important;
}

.subscription-modal-frame .modal-head,
.subscription-modal-frame .modal-actions,
.stacked-order-popup-header,
.stacked-order-popup-actions,
.product-editor-header,
.category-create-copy,
.customer-confirmation-next {
  border-color: var(--modal-header-border);
}

.subscription-modal-frame .modal-head,
.stacked-order-popup-header,
.product-editor-header,
.category-create-copy,
.customer-confirmation-next {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
}

:where(.subscription-modal-frame .modal-head h3, .stacked-order-popup-header h3, .product-editor-header h3, .category-create-copy h3, .customer-confirmation-next h3) {
  margin: 0;
  color: #102039;
  font-size: 22px;
  line-height: 1.1;
  letter-spacing: -0.055em;
}

:where(.subscription-modal-frame .modal-head p, .stacked-order-popup-header p, .product-editor-header p, .category-create-copy p, .customer-confirmation-next p) {
  margin: 6px 0 0;
  color: #667085;
  font-size: 12px;
  line-height: 1.5;
}

