.auth-verify-screen-card::after {
  display: none;
}

.auth-verify-card-body {
  padding: 20px 20px 24px;
}

.auth-otp-card {
  display: grid;
  width: 100%;
  justify-items: center;
  gap: 20px;
  padding: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  text-align: left;
}

.auth-otp-title {
  margin: 0;
  color: #000000;
