/* Admin storefront redesign layer from main nevari design system.html */
body {
  color: var(--ink);
  background:
    radial-gradient(circle at 14% 8%, rgba(255, 255, 255, 0.76), transparent 28%),
    radial-gradient(circle at 86% 5%, rgba(255, 255, 255, 0.80), transparent 26%),
    linear-gradient(145deg, #F8F4EE, var(--page));
}

.page-shell {
  max-width: 1420px;
  gap: 0;
  border: 1px solid rgba(255, 255, 255, 0.70);
  border-radius: var(--radius-xl);
  overflow: hidden;
  background: rgba(250, 247, 241, 0.86);
  box-shadow: var(--shadow-sm), var(--inset);
  backdrop-filter: blur(18px);
}

.page-shell .sidebar {
  top: 0;
  min-height: calc(100vh - 52px);
  border: 0;
  border-right: 1px solid rgba(10, 42, 94, 0.08);
