  background: linear-gradient(180deg, rgba(255, 255, 255, 0.66), rgba(255, 255, 255, 0.58));
  box-shadow: none;
}

.page-shell .main-shell {
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}

.brand-mark,
.side-brand .brand-mark {
  border-radius: 50%;
  background: var(--primary);
  color: var(--accent);
