  box-shadow: 0 12px 24px rgba(0, 0, 0, 0.12);
}

.nav-item {
  min-height: 42px;
  color: var(--primary);
  font-weight: 750;
}

.nav-item:hover {
  background: rgba(255, 255, 255, 0.56);
}

.nav-item.active {
  background: var(--primary);
  color: #fff;
