.section-hero-card,
.receipt-panel {
  border-radius: var(--radius-lg);
}

.section-hero-card {
  position: relative;
  overflow: hidden;
  background:
    linear-gradient(135deg, rgba(10, 42, 94, 0.98), rgba(10, 42, 94, 0.90)),
    var(--primary);
  color: #fff;
}

.section-hero-card::after {
  content: "";
  position: absolute;
  right: -80px;
  bottom: -120px;
  width: 330px;
  height: 330px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.20);
  pointer-events: none;
}

.section-hero-card>* {
  position: relative;
  z-index: 1;
}

.section-hero-card h1,
.section-hero-card h2,
.section-hero-card h3,
.panel-header h2,
.panel-header h3 {
  letter-spacing: -0.055em;
}

.section-hero-card p,
.section-hero-card .eyebrow,
.section-hero-card .section-kicker {
  color: rgba(255, 255, 255, 0.78);
}

.button-primary,
.pill-button.primary,
.btn-primary,
.segment.active,
.filter-btn.active,
.product-editor-tab.active,
.email-segmented-tab.active,
.audit-tab.active {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
  box-shadow: 0 12px 24px rgba(10, 42, 94, 0.18);
}

.button-primary:hover,
.pill-button.primary:hover,
.btn-primary:hover {
  background: var(--primary-700);
}

.pill-button,
.btn-outline,
.btn-soft,
.filter-btn,
.segment,
.product-editor-tab,
.email-segmented-tab,
.audit-tab,
.page-item,
.icon-button,
.select-wrap select,
.search-field,
.form-control,
.creation-field-grid .form-control,
.creation-field-grid textarea.form-control {
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.88);
  color: var(--primary);
  box-shadow: none;
}

.btn-soft,
.pill-button.soft {
  background: #ffffff;
  color: var(--primary);
  border-color: var(--line);
}

.pill-button.danger,
.btn-danger,
.table-action-button.danger {
  background: #ffffff;
  color: var(--danger);
  border-color: rgba(178, 59, 59, 0.20);
}

.pill-button.danger:hover,
.btn-danger:hover,
.table-action-button.danger:hover {
  background: rgba(178, 59, 59, 0.06);
}

.filter-bar,
.tabs-bar,
.segmented-mini,
.product-editor-tabs,
.email-segmented-tabs,
.audit-tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}

.filter-btn,
.segment,
.product-editor-tab,
.email-segmented-tab,
.audit-tab {
  min-height: 38px;
  border-radius: var(--pill);
  padding: 0 14px;
  font-size: 12px;
  font-weight: 800;
  white-space: nowrap;
}

.status-pill,
.chip,
.audit-pill,
.severity-pill,
.tone-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  min-height: 28px;
  padding: 0 11px;
  border-radius: var(--pill);
  border: 1px solid transparent;
  font-size: 12px;
  font-weight: 400;
  white-space: nowrap;
  box-shadow: none;
}

.status-pill:not(:has(.dot)):not(:has(.chip-dot))::before,
.chip:not(:has(.chip-dot))::before,
.audit-pill::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.status-pill.success,
.status-pill.paid,
.status-pill.completed,
.status-pill.confirmed,
.status-pill.available,
.chip.success,
.chip.paid,
.chip.completed,
.chip.confirmed,
.chip.available,
.tone-chip.green {
  color: var(--success);
  background: var(--success-bg);
  border-color: rgba(31, 138, 91, 0.20);
}

.status-pill.warning,
.status-pill.pending,
.chip.warning,
.chip.pending {
  color: var(--warning);
  background: var(--warning-bg);
  border-color: rgba(180, 106, 18, 0.22);
}

.status-pill.processing,
.chip.processing {
  color: #2c6eb7;
  background: #e2effc;
  border-color: rgba(44, 110, 183, 0.22);
}

.status-pill.info,
.chip.info,
.tone-chip.blue,
.severity-pill.info {
  color: var(--info);
  background: var(--info-bg);
  border-color: rgba(44, 110, 183, 0.22);
}

.status-pill.error,
.status-pill.danger,
.status-pill.cancelled,
.status-pill.failed,
.status-pill.expired,
.chip.error,
.chip.danger,
.chip.cancelled,
.chip.failed,
.chip.expired {
  color: var(--danger);
  background: var(--danger-bg);
  border-color: rgba(178, 59, 59, 0.20);
}

.status-pill.refunded,
.chip.refunded,
.tone-chip.purple {
  color: var(--purple);
  background: var(--purple-bg);
  border-color: rgba(118, 86, 165, 0.20);
}

.status-pill.neutral,
.status-pill.draft,
.chip.neutral,
.chip.draft {
  color: #526274;
  background: #eef1f5;
  border-color: rgba(82, 98, 116, 0.20);
}

.table-scroll,
.table-wrap,
.audit-table-wrap {
  border: 1px solid rgba(10, 42, 94, 0.08);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.58);
  overflow-x: auto;
  padding: 20px
}

table {
  border-collapse: collapse;
}

th {
  color: var(--muted);
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

td {
  border-top: 1px solid rgba(10, 42, 94, 0.08);
  color: var(--ink);
}

.interactive-row,
.table-row-button,
.product-card,
.product-category-row,
.product-category-product-card,
.rx-calendar-day,
.consultation-search-result,
.doctor-mini {
  transition: transform 0.14s ease, border-color 0.14s ease, background 0.14s ease, box-shadow 0.14s ease;
}

.interactive-row:hover,
.table-row-button:hover,
.product-card:hover,
.product-category-row:hover,
.product-category-product-card:hover,
.consultation-search-result:hover,
.doctor-mini:hover {
  background: #fff;
}

.product-thumb,
.product-image,
.product-photo,
.receipt-line-item-fallback,
.receipt-line-item-image,
.order-product-image {
  border-radius: 18px;
  background: linear-gradient(145deg, var(--accent), #FFF8EF);
  box-shadow: var(--inset);
}

.booking-calendar-nav,
.rx-calendar-nav-btn {
  border-radius: var(--pill);
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.78);
  color: var(--primary);
  box-shadow: var(--inset);
}

.rx-calendar-day,
.booking-calendar-day,
.consultation-calendar-day {
  border-radius: 18px;
  border: 1px solid rgba(10, 42, 94, 0.10);
  background: rgba(255, 255, 255, 0.62);
}

.rx-calendar-day.selected,
.rx-calendar-day.today,
.booking-calendar-day.active,
.consultation-calendar-day.active {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
  box-shadow: 0 14px 26px rgba(10, 42, 94, 0.16);
}

.rx-availability-board,
.availability-board,
.doctor-availability-card {
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  background: var(--surface);
  box-shadow: var(--shadow-xs), var(--inset);
}

.app-modal-backdrop,
.modal-backdrop {
  background: rgba(6, 27, 63, 0.34);
  backdrop-filter: blur(6px);
}

.stacked-order-popup,
.product-editor-modal,
.category-create-popup,
.order-modal,
.receipt-popup,
.assignment-popup,
.consultation-create-popup,
.profile-create-popup,
.subscription-modal-frame {
  border: 1px solid rgba(255, 255, 255, 0.78);
  border-radius: 30px;
  background: #FBF8F3;
  box-shadow: var(--shadow-md), var(--inset);
}

.order-modal-topbar,
.stacked-order-popup-header,
.product-editor-header,
.modal-head,
.category-create-copy {
  border-bottom: 1px solid rgba(10, 42, 94, 0.08);
  background: linear-gradient(180deg, rgba(251, 248, 243, 0.98), rgba(251, 248, 243, 0.92));
}

.stacked-order-popup-actions,
.product-editor-actions,
.modal-actions,
.category-create-actions,
.receipt-footer-actions {
  border-top: 1px solid rgba(10, 42, 94, 0.08);
  background: linear-gradient(180deg, rgba(251, 248, 243, 0.82), rgba(251, 248, 243, 0.98));
}

.receipt-popup-redesign .receipt-hero,
.payment-hero-card,
.document-total-band {
  background:
    linear-gradient(135deg, rgba(10, 42, 94, 0.98), rgba(10, 42, 94, 0.90)),
    var(--primary);
  color: #fff;
  border-radius: 28px;
  box-shadow: 0 18px 42px rgba(10, 42, 94, 0.18);
}

.consultation-create-popup.consultation-design-popup {
  width: min(1100px, calc(100vw - 60px));
  border-radius: 36px;
  background: linear-gradient(180deg, rgba(253, 250, 245, 0.98), rgba(250, 247, 241, 0.98));
}

.consultation-create-popup.consultation-design-popup .create-record-form {
  max-height: calc(100vh - 72px);
  overflow: hidden;
}

.consultation-create-popup.consultation-design-popup .stacked-order-popup-actions {
  padding: 22px 30px 30px;
  justify-content: flex-end;
}

@media (max-width: 900px) {
  .consultation-create-popup.consultation-design-popup {
    width: min(100vw - 24px, 720px);
    border-radius: 28px;
  }

  .consultation-design-popup .stacked-order-popup-header {
    padding: 24px 22px 20px;
    align-items: flex-start;
  }

  .consultation-design-shell {
    grid-template-columns: 1fr;
    padding: 18px;
  }

  .consultation-design-grid {
    grid-template-columns: 1fr;
  }

  .consultation-design-summary {
    order: 2;
  }

  .consultation-create-popup.consultation-design-popup .stacked-order-popup-actions {
    padding: 18px;
  }
}

@media (max-width: 560px) {
  .consultation-create-popup.consultation-design-popup {
    width: calc(100vw - 16px);
    border-radius: 24px;
  }

  .consultation-design-popup .stacked-order-popup-header h3 {
    font-size: 24px;
  }

  .consultation-design-popup .stacked-order-popup-header p {
    font-size: 14px;
  }

  .consultation-design-form-card,
  .consultation-design-summary {
    padding: 16px;
    border-radius: 22px;
  }

  .consultation-design-summary-icon {
    width: 88px;
    height: 88px;
    border-radius: 28px;
  }

  .consultation-design-summary-list div {
    grid-template-columns: 1fr;
    gap: 4px;
  }

  .consultation-design-summary-list strong {
    text-align: left;
  }

  .consultation-create-popup.consultation-design-popup .stacked-order-popup-actions {
    display: grid;
    grid-template-columns: 1fr;
  }

  .consultation-design-popup .stacked-order-popup-actions .pill-button,
  .consultation-design-popup .stacked-order-popup-actions .button-secondary,
  .consultation-design-popup .stacked-order-popup-actions .button-primary {
    width: 100%;
  }
}

@media (min-width: 981px) {
  .page-shell {
    grid-template-columns: var(--sidebar-width) minmax(0, 1fr);
    align-items: stretch;
  }

  .page-shell .sidebar {
    position: sticky;
    left: auto;
    width: auto;
    height: auto;
    min-height: calc(100dvh - 52px);
    overflow: visible;
    z-index: 2;
    display: flex;
  }

  .page-shell .main-shell {
    grid-column: 2;
  }
}

.invoice-paper,
.receipt-paper,
.document-preview,
.receipt-panel,
.receipt-items-panel {
  border: 1px solid rgba(10, 42, 94, 0.10);
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.88);
  box-shadow: var(--shadow-xs), var(--inset);
}

.form-control,
input,
select,
textarea {
  accent-color: var(--primary);
}

input:focus-visible,
select:focus-visible,
textarea:focus-visible,
button:focus-visible,
.form-control:focus-visible {
  outline: 3px solid rgba(44, 110, 183, 0.22);
  outline-offset: 2px;
}

@media (max-width: 900px) {
  body {
    padding: 14px;
  }

  .page-shell {
    display: block;
    border-radius: 24px;
  }

  .page-shell .sidebar {
    border-right: 0;
    border-bottom: 1px solid rgba(10, 42, 94, 0.08);
    min-height: auto;
  }

  .metric-grid,
  .overview-v2-grid,
  .orders-layout,
  .products-layout,
  .consultation-layout,
  .doctor-grid,
  .receipt-body-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 720px) {

  .filter-bar,
  .tabs-bar,
  .segmented-mini,
  .product-editor-tabs,
  .email-segmented-tabs,
  .audit-tabs {
    overflow-x: auto;
    flex-wrap: nowrap;
    padding-bottom: 4px;
  }

  .button-primary,
  .pill-button,
  .btn,
  .receipt-send-button {
    min-width: 0;
    max-width: 100%;
  }

  .stacked-order-popup,
  .product-editor-modal,
  .category-create-popup,
  .order-modal,
  .receipt-popup,
  .subscription-modal-frame {
    width: min(100%, calc(100vw - 18px));
    max-height: calc(100vh - 18px);
    border-radius: 24px;
  }
}

.doctor-appointment-note {
  margin-top: 16px;
  padding: 14px 16px;
  border: 1px solid rgba(14, 41, 85, 0.12);
  border-radius: 18px;
  background: rgba(14, 41, 85, 0.04);
}

.doctor-appointment-note span {
  display: block;
  font-size: 12px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #6b7890;
  margin-bottom: 8px;
}

.doctor-appointment-note p {
  margin: 0;
  color: #17325c;
}

.doctor-completion-modal {
  position: fixed;
  inset: 0;
  z-index: 1200;
  display: grid;
  place-items: center;
  padding: 24px;
}

.doctor-completion-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(10, 21, 42, 0.48);
}

.doctor-completion-card {
  position: relative;
  width: min(760px, 100%);
  max-height: min(88vh, 920px);
  overflow: auto;
  padding: 24px;
  border-radius: 28px;
  background: #fffdf8;
  box-shadow: 0 28px 80px rgba(14, 41, 85, 0.2);
  border: 1px solid rgba(14, 41, 85, 0.08);
}

.doctor-completion-head {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: flex-start;
  margin-bottom: 18px;
}

.doctor-completion-head h3 {
  margin: 0 0 6px;
  color: #0e2955;
}

.doctor-completion-head p {
  margin: 0;
  color: #66758f;
}

.doctor-completion-products {
  margin-top: 18px;
  padding: 18px;
  border-radius: 22px;
  border: 1px solid rgba(14, 41, 85, 0.1);
  background: #ffffff;
}

.doctor-completion-products-head {
  display: grid;
  gap: 4px;
  margin-bottom: 12px;
}

.doctor-completion-products-head strong {
  color: #0e2955;
}

.doctor-completion-products-head span {
  color: #66758f;
  font-size: 14px;
}

.doctor-completion-product-row {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: center;
  padding: 12px 0;
  border-top: 1px solid rgba(14, 41, 85, 0.08);
}

.doctor-completion-product-row:first-of-type {
  border-top: 0;
}

.doctor-completion-product-row div {
  display: grid;
  gap: 4px;
}

.doctor-completion-product-row span {
  color: #66758f;
  font-size: 13px;
}

.doctor-completion-product-row input {
  width: 88px;
  min-width: 88px;
  border-radius: 14px;
  border: 1px solid rgba(14, 41, 85, 0.18);
  padding: 10px 12px;
  background: #fff;
}

.doctor-completion-actions {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 20px;
}

@media (max-width: 720px) {
  .doctor-completion-modal {
    padding: 12px;
  }

  .doctor-completion-card {
    padding: 18px;
    border-radius: 22px;
  }

  .doctor-completion-head,
  .doctor-completion-actions,
  .doctor-completion-product-row {
    flex-direction: column;
    align-items: stretch;
  }

  .doctor-completion-product-row input {
    width: 100%;
    min-width: 0;
  }
}

.customer-mobile-full-therapy-shell {
  min-height: calc(100dvh - 180px);
  display: grid;
  align-content: center;
}

.doctor-flow-shell {
  --flow-navy-950: var(--primary-900);
  --flow-navy-900: var(--primary);
  --flow-navy-800: var(--primary);
  --flow-navy-700: var(--primary-700);
  --flow-text-primary: var(--ink);
  --flow-text-secondary: var(--muted);
  --flow-text-muted: var(--subtle);
  --flow-line: var(--line);
  --flow-border: var(--line-strong);
  --flow-surface: rgba(255, 255, 255, 0.92);
  --flow-surface-soft: rgba(255, 255, 255, 0.62);
  --flow-surface-pill: rgba(255, 255, 255, 0.78);
  --flow-input: #ffffff;
  --flow-success: var(--success);
  --flow-success-soft: var(--success-bg);
  --flow-warning: var(--warning);
  --flow-warning-soft: var(--warning-bg);
  --flow-danger: var(--danger);
  --flow-danger-soft: var(--danger-bg);
  --flow-info-soft: var(--info-bg);
  --flow-radius-sm: 12px;
  --flow-radius-md: 12px;
  --flow-radius-lg: 12px;
  --flow-radius-xl: 12px;
  --flow-radius-pill: 999px;
  --page-gutter: clamp(16px, 3vw, 40px);
  --sidebar-width: 280px;
  width: 100%;
  min-height: 100vh;
  min-height: 100dvh;
  background: var(--page);
  color: var(--flow-text-primary);
  font-family: var(--font-family);
  overflow-x: clip;
}

.doctor-flow-shell * {
  box-sizing: border-box;
}

.doctor-flow-shell .app-shell {
  width: 100%;
  max-width: 1600px;
  height: 100vh;
  height: 100dvh;
  min-height: 100vh;
  min-height: 100dvh;
  margin-inline: auto;
  padding: 20px;
  display: grid;
  grid-template-columns: var(--sidebar-width) minmax(0, 1fr);
  align-items: stretch;
  gap: 22px;
}

.doctor-flow-shell .sidebar {
  position: sticky;
  top: 20px;
  align-self: start;
  min-height: calc(100vh - 40px);
  padding: 28px 22px 20px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  background: var(--flow-surface);
  border: 1px solid var(--flow-line);
  border-radius: 12px;
  box-shadow: var(--shadow-soft);
}

.doctor-flow-shell .brand {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 2px 0 28px;
}

.doctor-flow-shell .brand-mark {
  width: 32px;
  height: 32px;
  flex: 0 0 32px;
  overflow: hidden;
  border-radius: 50%;
  background: transparent;
  border: 0;
  outline: 0;
}

.doctor-flow-shell .brand-mark img {
  width: 100%;
  height: 100%;
  display: block;
  object-fit: cover;
}

.doctor-flow-shell .brand-title {
  margin: 0;
  color: var(--flow-navy-900);
  font-size: 16px;
  line-height: 1.2;
  font-weight: 650;
  letter-spacing: -0.025em;
}

.doctor-flow-shell .brand-subtitle {
  display: block;
  margin-top: 3px;
  color: var(--flow-text-secondary);
  font-size: 13px;
  font-weight: 450;
}

.doctor-flow-shell .nav-label {
  margin: 0 8px 14px;
  color: var(--flow-text-secondary);
  font-size: 12px;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.doctor-flow-shell .nav-list {
  display: grid;
  gap: 4px;
}

.doctor-flow-shell .nav-list .nav-logout {
  margin-top: 16px;
  border: 0;
  color: var(--flow-danger);
}

.doctor-flow-shell .nav-list .nav-logout:hover {
  background: rgba(178, 59, 59, 0.08);
}

.doctor-flow-shell .nav-item {
  min-height: 48px;
  padding: 0 10px;
  display: flex;
  align-items: center;
  gap: 12px;
  border: 0;
  border-radius: var(--flow-radius-pill);
  background: transparent;
  color: #7a8494;
  text-align: left;
  font-size: 14px;
  font-weight: 500;
  transition: background 0.18s ease, color 0.18s ease;
}

.doctor-flow-shell .nav-item:hover {
  background: rgba(10, 42, 94, 0.05);
}

.doctor-flow-shell .nav-item.active {
  background: var(--primary);
  color: #fff;
}

.doctor-flow-shell .nav-icon {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: rgba(10, 42, 94, 0.06);
  border: 0;
  color: currentColor;
  flex: 0 0 auto;
}

.doctor-flow-shell .nav-item.active .nav-icon {
  background: rgba(255, 255, 255, 0.16);
  color: #fff;
}

.doctor-flow-shell .main {
  min-width: 0;
  height: calc(100vh - 40px);
  height: calc(100dvh - 40px);
  min-height: calc(100vh - 40px);
  min-height: calc(100dvh - 40px);
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  align-self: stretch;
  overflow-y: auto;
  overflow-x: hidden;
  scrollbar-gutter: stable;
  gap: 18px;
