.doctor-flow-shell .switch input {
  position: absolute;
  opacity: 0;
  inset: 0;
  margin: 0;
}

.doctor-flow-shell .switch-ui {
  width: 100%;
  height: 100%;
  border-radius: 999px;
  border: 1px solid var(--flow-border);
  background: #fff;
  position: relative;
  transition: background 0.16s ease, border-color 0.16s ease;
}

.doctor-flow-shell .switch-ui::after {
  content: "";
  position: absolute;
  top: 4px;
  left: 4px;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  background: var(--flow-text-muted);
  transition: transform 0.16s ease, background 0.16s ease;
}

.doctor-flow-shell .switch input:checked+.switch-ui {
  background: var(--flow-navy-800);
  border-color: var(--flow-navy-800);
}

.doctor-flow-shell .switch input:checked+.switch-ui::after {
  transform: translateX(22px);
  background: #fff;
}

