  background: transparent;
  cursor: pointer;
}

.doctor-mobile-menu-button span {
  display: block;
  width: 18px;
  height: 2px;
  border-radius: 999px;
  background: #163a7a;
}

.doctor-mobile-welcome {
  margin: 0;
  font-size: 1.05rem;
  color: #3e5173;
}

.doctor-mobile-content {
  padding-bottom: 32px;
}

.doctor-mobile-page {
  display: grid;
  gap: 24px;
  width: 100%;
  min-width: 0;
}

.doctor-mobile-page-section {
  display: grid;
  gap: 16px;
  min-width: 0;
}

.doctor-mobile-page-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.doctor-mobile-page-title {
  margin: 0 0 12px;
  color: #0b326d;
  font-size: 20px;
  font-weight: 500;
  line-height: 1.25;
}

.doctor-mobile-inline-link {
  border: 0;
  background: transparent;
  padding: 0;
  color: #163a7a;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.doctor-mobile-metric-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.doctor-mobile-metric-grid.compact {
  gap: 12px;
}

.doctor-mobile-metric-card,
.doctor-mobile-surface-card,
.doctor-mobile-consultation-card,
.doctor-mobile-day-card {
  border-radius: 16px;
  border: 1px solid rgba(21, 58, 122, 0.12);
  background: #ffffff;
  box-shadow: 0 10px 24px rgba(18, 39, 84, 0.04);
}

.doctor-mobile-metric-card {
  min-height: 136px;
  border-radius: 13px;
  border: 1px solid #e2e4e9;
  background: #f6f8fa;
  padding: 14px 12px 13px;
  display: grid;
  grid-template-rows: 44px auto 1fr;
  gap: 8px;
  min-width: 0;
  overflow: hidden;
  box-sizing: border-box;
}

.doctor-mobile-metric-icon,
.doctor-mobile-overview-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  border-radius: 50%;
  border: 1px solid rgba(21, 58, 122, 0.14);
  color: #163a7a;
  background: #ffffff;
}

.doctor-mobile-metric-label,
.doctor-mobile-form-field span {
  font-size: 14px;
  line-height: 1.2;
  color: #65748e;
}

.doctor-mobile-metric-value {
  display: block;
  width: 100%;
  min-width: 0;
  max-width: 100%;
  font-size: clamp(20px, 6vw, 24px);
  line-height: 1.08;
  color: #163a7a;
  font-weight: 400;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: clip;
  align-self: start;
  padding-right: 2px;
}

.doctor-mobile-appointment-listing,
.doctor-mobile-card-stack,
.doctor-mobile-toggle-stack {
  display: grid;
  gap: 16px;
}

.doctor-mobile-overview-item {
  display: flex;
  grid-template-columns: auto minmax(0, 1fr) auto;
  gap: 12px;
  align-items: flex-start;
  padding: 0 0 16px;
  border-bottom: 1px solid rgba(21, 58, 122, 0.12);
  cursor: pointer;
  min-width: 0;
  justify-content: space-between;
}

.doctor-mobile-overview-item:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.doctor-mobile-overview-copy {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.doctor-mobile-overview-copy strong {
  color: #525866;
  font-size: 16px;
  font-weight: 500;
  line-height: 1.25;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-transform: capitalize;
}

.doctor-mobile-overview-copy span {
  color: #7e8798 !important;
  font-size: 12px !important;
  line-height: 1.35;
}

.doctor-mobile-status-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 30px;
  max-width: 100%;
  padding: 0 14px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 300;
  white-space: nowrap;
  align-content: center;
}

.doctor-mobile-status-pill::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: currentColor;
}

.doctor-mobile-status-pill.success {
  color: #1f8e57;
  background: #e6f8ee;
  border: 1px solid #c9ecd7;
}

.doctor-mobile-status-pill.warning {
  color: #c47a15;
  background: #fff3dc;
  border: 1px solid #f3d59c;
}

.doctor-mobile-status-pill.processing {
  color: #2c6eb7;
  background: #e2effc;
  border: 1px solid rgba(44, 110, 183, 0.22);
}

.doctor-mobile-status-pill.pending {
  color: #c47a15;
  background: #fff3dc;
  border: 1px solid #f3d59c;
}

.doctor-mobile-status-pill.danger {
  color: #d55b54;
  background: #ffe8e5;
  border: 1px solid #f6c4be;
}

.doctor-mobile-filter-strip {
  display: flex;
  gap: 10px;
  overflow-x: auto;
  padding-bottom: 2px;
  scrollbar-width: none;
}

.doctor-mobile-filter-strip::-webkit-scrollbar {
  display: none;
}

.doctor-mobile-filter-pill {
  flex: 0 0 auto;
  border: 1px solid rgba(21, 58, 122, 0.14);
  border-radius: 999px;
  background: #ffffff;
  padding: 10px 14px;
  color: #163a7a;
  font: inherit;
  cursor: pointer;
}

.doctor-mobile-filter-pill.active {
  background: #163a7a;
  border-color: #163a7a;
  color: #ffffff;
}

.doctor-mobile-filter-strip.schedule {
  flex-wrap: wrap;
}

.doctor-mobile-consultation-card {
  display: grid;
  gap: 14px;
  padding: 16px;
  min-width: 0;
}

.doctor-mobile-consultation-top {
  display: flex;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 12px;
  align-items: flex-start;
  min-width: 0;
  justify-content: space-between;
}

.doctor-mobile-consultation-lead {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  min-width: 0;
}

.doctor-mobile-consultation-top strong {
  display: block;
  color: #163a7a;
  text-transform: capitalize;
}

.doctor-mobile-consultation-top span,
.doctor-mobile-consultation-meta span {
  display: block;
  color: #65748e;
}

.consultation-reason {
  font-size: 14px;
  margin-top: 16px;
  color: #424242 !important;

}

.consultation-email,
.consultation-window,
.consultation-timezone {
  font-size: 12px;
}

.consultation-window {
  font-weight: 500;
}

.doctor-mobile-consultation-meta {
  display: grid;
  padding-top: 8px;
  gap: 4px;
  min-width: 0;
  border-top: solid 0.1px #e2e2e2e2;
}



.doctor-mobile-card-actions,
.doctor-mobile-stacked-actions {
  display: grid;
  gap: 10px;
  width: 100%;
}

.doctor-mobile-action-button,
.doctor-mobile-save-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 42px;
  width: 100%;
  border-radius: 999px;
  padding: 0 16px;
  text-decoration: none;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.doctor-mobile-action-button.primary,
.doctor-mobile-save-button {
  border: 1px solid #163a7a;
  background: #163a7a;
  color: #ffffff;
  width: fit-content;
}

.doctor-mobile-action-button.secondary {
  border: 1px solid #163a7a;
  background: #ffffff;
  color: #163a7a;
}

.doctor-mobile-action-button.danger {
  border: 1px solid rgba(178, 59, 59, 0.32);
  background: #ffffff;
  color: #b23b3b;
}

.doctor-mobile-action-button.wide {
  width: 100%;
}

.doctor-mobile-empty-card {
  padding: 18px 16px;
  border-radius: 16px;
  border: 1px dashed rgba(21, 58, 122, 0.18);
  background: rgba(255, 255, 255, 0.88);
  color: #65748e;
}

.doctor-mobile-surface-card {
  display: grid;
  gap: 16px;
  padding: 16px;
  min-width: 0;
}

.doctor-mobile-surface-head {
  display: grid;
  gap: 6px;
}

.doctor-mobile-surface-head h2 {
  margin: 0;
  font-size: 1.2rem;
  color: #163a7a;
}

.doctor-mobile-surface-head p {
  margin: 0;
  color: #65748e;
}

.doctor-mobile-day-card {
  overflow: hidden;
}

.doctor-mobile-day-summary {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 16px;
  cursor: pointer;
  list-style: none;
}

.doctor-mobile-day-summary::-webkit-details-marker {
  display: none;
}

.doctor-mobile-day-summary strong {
  display: block;
  color: #163a7a;
}

.doctor-mobile-day-summary span {
  display: block;
  margin-top: 4px;
  color: #65748e;
  font-size: 0.92rem;
}

.doctor-mobile-day-controls {
  display: grid;
  gap: 10px;
  justify-items: end;
}

.doctor-mobile-day-body {
  display: grid;
  gap: 14px;
  padding: 0 16px 16px;
}

.doctor-mobile-slot-group {
  display: grid;
  gap: 10px;
}

.doctor-mobile-slot-head strong {
  color: #163a7a;
}

.doctor-mobile-slot-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  width: 100%;
}

.doctor-mobile-slot-chip {
  border: 1px solid rgba(21, 58, 122, 0.14);
  border-radius: 999px;
  background: #ffffff;
  padding: 8px 12px;
  color: #163a7a;
  font: inherit;
  font-size: 0.88rem;
  cursor: pointer;
}

.doctor-mobile-slot-chip.active {
  background: #163a7a;
  border-color: #163a7a;
  color: #ffffff;
}

.doctor-mobile-slot-chip:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}

.doctor-mobile-form-stack {
  display: grid;
  gap: 14px;
}

.doctor-mobile-form-field {
  display: grid;
  gap: 8px;
}

.doctor-mobile-form-field input,
.doctor-mobile-form-field textarea {
  width: 100%;
  border: 1px solid rgba(21, 58, 122, 0.12);
  border-radius: 14px;
  background: #fdfcf9;
  padding: 12px 14px;
  color: #163a7a;
  font: inherit;
  outline: none;
}

.doctor-mobile-form-field textarea {
  resize: vertical;
}

.doctor-mobile-shell .doctor-setting-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  border-top: 1px solid rgba(21, 58, 122, 0.1);
  padding-top: 14px;
  color: #163a7a;
}

.doctor-mobile-shell .doctor-setting-toggle:first-child {
  border-top: 0;
  padding-top: 0;
}

.doctor-mobile-shell .customer-mobile-header {}

.doctor-mobile-shell .customer-mobile-header-spacer.is-overview {
  height: 132px;
}

.doctor-mobile-drawer-footer {
  padding-top: 12px;
}

.doctor-mobile-drawer-profile strong,
.doctor-mobile-drawer-profile span {
  display: block;
}

.doctor-mobile-shell .btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  border-radius: 999px;
  padding: 0 16px;
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}

.doctor-mobile-shell .btn.secondary {
  border: 1px solid rgba(21, 58, 122, 0.14);
  background: #ffffff;
  color: #163a7a;
}

.doctor-mobile-shell .btn.small {
  min-height: 38px;
  padding: 0 14px;
}

.doctor-pagination {
  display: flex;
  align-items: center;
}

.doctor-mobile-shell .doctor-pagination {
  justify-content: space-between;
  padding-top: 4px;
}

.doctor-mobile-shell .doctor-pagination .btn.secondary.small {
  min-width: 102px;
}

@media (min-width: 721px) {
  .doctor-mobile-shell {
    display: none;
  }
}

@media (max-width: 420px) {

  .doctor-mobile-content,
  .doctor-mobile-header {
    padding-left: 16px;
    padding-right: 16px;
  }

  .doctor-mobile-metric-grid {


    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    grid-gap: 8px;
    gap: 8px;
  }

  .doctor-mobile-overview-item,
  .doctor-mobile-consultation-top {
    grid-template-columns: 1fr;
  }

  .doctor-mobile-overview-icon {
    display: none;
  }
}

@media (max-width: 1100px) {
  .doctor-flow-shell .app-shell {
    grid-template-columns: 1fr;
    height: auto;
    padding: 16px;
    min-height: auto;
  }

  .doctor-flow-shell .sidebar {
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    width: min(75vw, 300px);
    z-index: 30;
    transform: translateX(-110%);
    transition: transform 0.22s ease;
    min-height: 100vh;
    min-height: 100dvh;
    border-radius: 0 12px 12px 0;
    overflow-y: auto;
    background: #ffffff;
  }

  .doctor-flow-shell .sidebar.is-open {
    transform: translateX(0);
  }

  .doctor-flow-shell .dashboard-side-nav-backdrop {
    position: fixed;
    inset: 0;
    display: block;
    z-index: 20;
    background: rgba(6, 27, 66, 0.35);
  }

  .doctor-flow-shell .dashboard-tablet-toolbar {
    display: flex;
    justify-content: flex-start;
    position: sticky;
    top: 0;
    z-index: 12;
    padding-bottom: 4px;
    background: linear-gradient(180deg, rgba(243, 245, 249, 0.98), rgba(243, 245, 249, 0.82), rgba(243, 245, 249, 0));
  }

  .doctor-flow-shell .dashboard-menu-button {
    width: 48px;
    height: 48px;
    border-radius: 50%;
    border: 1px solid var(--flow-border);
    background: #fff;
    display: grid;
    gap: 4px;
    place-content: center;
  }

  .doctor-flow-shell .dashboard-menu-button span {
    display: block;
    width: 18px;
    height: 2px;
    background: var(--flow-navy-900);
    border-radius: 999px;
  }

  .doctor-flow-shell .availability-layout,
  .doctor-flow-shell .doctor-flow-grid-two,
  .doctor-flow-shell .flow-settings-grid,
  .doctor-flow-shell .consultations-workspace,
  .doctor-flow-shell .consultation-table-top,
  .doctor-flow-shell .consultation-summary-grid,
  .doctor-flow-shell .day-controls {
    grid-template-columns: 1fr;
  }

  .doctor-flow-shell .summary-column {
    position: static;
  }

  .doctor-flow-shell .consultation-calendar-pane,
  .doctor-flow-shell .consultation-appointment-pane {
    height: auto;
  }

  .doctor-flow-shell .profile-form-grid,
  .doctor-flow-shell .consultation-detail-grid,
  .doctor-flow-shell .consultation-stats,
  .doctor-flow-shell .overview-metric-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .doctor-flow-shell .overview-welcome-strip,
  .doctor-flow-shell .overview-section-head,
  .doctor-flow-shell .profile-card-header,
  .doctor-flow-shell .consultation-pane-head {
    flex-direction: column;
    align-items: stretch;
  }

  .doctor-flow-shell .consultation-filter-controls,
  .doctor-flow-shell .doctor-pagination {
    flex-direction: column;
    align-items: stretch;
  }

  .doctor-flow-shell .consultations-workspace {
    min-height: 0;
    height: auto;
  }

  .doctor-flow-shell .main {
    height: calc(100vh - 32px);
    height: calc(100dvh - 32px);
    min-height: auto;
    grid-template-rows: auto minmax(0, 1fr) auto;
    overflow-y: auto;
    overflow-x: hidden;
  }

  .doctor-flow-shell .page-body {
    min-height: 0;
    overflow: visible;
  }

  .doctor-flow-shell .bottom-nav.desktop-bottom-nav {
    position: sticky;
    bottom: 12px;
    z-index: 10;
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    padding: 10px;
    border-radius: 24px;
    background: rgba(255, 255, 255, 0.92);
    border: 1px solid var(--flow-line);
    backdrop-filter: blur(16px);
  }

  .doctor-flow-shell .bottom-nav .nav-item {
    flex: 1 1 calc(25% - 8px);
    min-width: 0;
    justify-content: center;
  }
}

@media (max-width: 720px) {
  .doctor-flow-shell .consultation-search {
    min-width: 0;
    width: 100%;
  }

  .doctor-flow-shell .consultation-date-field {
    min-width: 0;
  }

  .doctor-flow-shell .appointment-top,
  .doctor-flow-shell .overview-row,
  .doctor-flow-shell .review-entry-head {
    grid-template-columns: 1fr;
  }

  .doctor-flow-shell .consultation-detail-grid,
  .doctor-flow-shell .profile-form-grid,
  .doctor-flow-shell .consultation-stats,
  .doctor-flow-shell .overview-metric-grid,
  .doctor-flow-shell .flow-settings-grid {
    grid-template-columns: 1fr;
  }

  .doctor-flow-shell .doctor-table-actions {
    justify-content: flex-start;
  }

  .doctor-flow-shell .doctor-appointments-table-wrap {
    display: none;
  }

  .doctor-flow-shell .doctor-mobile-appointment-list {
    display: grid;
    gap: 12px;
  }

  .doctor-flow-shell .doctor-mobile-appointment-grid {
    grid-template-columns: 1fr;
  }

  .doctor-flow-shell .doctor-appointments-panel {
    padding: 20px;
  }

  .doctor-flow-shell .setup-bar {
    grid-template-columns: 1fr;
  }

  .doctor-flow-shell .bottom-nav.desktop-bottom-nav {
    bottom: 10px;
  }

  .doctor-flow-shell .bottom-nav .nav-item {
    flex: 1 1 calc(50% - 8px);
    min-width: 0;
    justify-content: center;
  }

  .doctor-flow-shell .main {
    padding-bottom: 12px;
  }

  .doctor-flow-shell .page-body {
    padding-bottom: 88px;
  }
}

.nevari-admin-storefront {
  --admin-surface-bg: linear-gradient(180deg, rgba(255, 252, 246, 0.98) 0%, rgba(251, 247, 239, 0.96) 100%);
  --admin-surface-border: rgba(196, 178, 150, 0.28);
  --admin-surface-shadow: 0 24px 48px rgba(25, 44, 78, 0.1), 0 8px 18px rgba(25, 44, 78, 0.05);
  --admin-surface-shadow-soft: 0 16px 30px rgba(25, 44, 78, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.74);
  --admin-surface-radius: 28px;
  --admin-surface-radius-sm: 18px;
  --admin-ink: #16386a;
  --admin-muted: #6f7f99;
  --admin-line: rgba(24, 55, 101, 0.12);
  --admin-pill-bg: rgba(255, 255, 255, 0.82);
  --admin-page-gap: clamp(18px, 2vw, 28px);
}

.nevari-admin-storefront .pages-stack {
  gap: var(--admin-page-gap);
}

.nevari-admin-storefront .page-banner,
.nevari-admin-storefront .operations-grid>.panel.compact:first-child,
.nevari-admin-storefront .overview-v2-panel:first-child,
.nevari-admin-storefront .doctor-settings-card:first-child {
  position: relative;
  overflow: hidden;
  border: 1px solid var(--admin-surface-border);
  border-radius: var(--admin-surface-radius);
  background:
    radial-gradient(circle at top right, rgba(204, 227, 255, 0.62), transparent 32%),
    radial-gradient(circle at top left, rgba(255, 221, 178, 0.36), transparent 28%),
    var(--admin-surface-bg);
  box-shadow: var(--admin-surface-shadow);
}

.nevari-admin-storefront .page-banner::before,
.nevari-admin-storefront .operations-grid>.panel.compact:first-child::before,
.nevari-admin-storefront .overview-v2-panel:first-child::before,
.nevari-admin-storefront .doctor-settings-card:first-child::before {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.4), transparent 42%);
}

.nevari-admin-storefront .page-banner,
.nevari-admin-storefront .operations-grid>.panel.compact:first-child {
  padding: clamp(22px, 3vw, 34px);
}

.nevari-admin-storefront .page-banner h1,
.nevari-admin-storefront .page-banner h2,
.nevari-admin-storefront .page-banner h3,
.nevari-admin-storefront .operations-grid>.panel.compact:first-child h1,
.nevari-admin-storefront .operations-grid>.panel.compact:first-child h2,
.nevari-admin-storefront .operations-grid>.panel.compact:first-child h3,
.nevari-admin-storefront .panel-header h3 {
  color: var(--admin-ink);
  letter-spacing: -0.03em;
}

.nevari-admin-storefront .page-banner p,
.nevari-admin-storefront .operations-grid>.panel.compact:first-child p,
.nevari-admin-storefront .panel-header p,
.nevari-admin-storefront .muted {
  color: var(--admin-muted);
}

.nevari-admin-storefront .section-kicker,
.nevari-admin-storefront .page-banner .section-kicker,
.nevari-admin-storefront .panel-header .section-kicker {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 6px 12px;
  border: 1px solid rgba(31, 93, 178, 0.18);
  border-radius: 999px;
  background: rgba(235, 244, 255, 0.88);
  color: #2f6dcb;
  font-weight: 700;
  letter-spacing: 0;
}

.nevari-admin-storefront .mini-stat-grid,
.nevari-admin-storefront .metrics-grid,
.nevari-admin-storefront .banner-stats,
.nevari-admin-storefront .overview-metric-grid,
.nevari-admin-storefront .order-summary-grid {
  gap: 16px;
}

.nevari-admin-storefront .mini-stat,
.nevari-admin-storefront .metric-card,
.nevari-admin-storefront .banner-stat,
.nevari-admin-storefront .order-mini-stat,
.nevari-admin-storefront .detail-item-card,
.nevari-admin-storefront .history-card {
  border: 1px solid rgba(24, 55, 101, 0.1);
  border-radius: 22px;
  background: rgba(255, 255, 255, 0.84);
  box-shadow: var(--admin-surface-shadow-soft);
}

.nevari-admin-storefront .mini-stat,
.nevari-admin-storefront .metric-card,
