.customer-profile-cropper-surface {
  position: relative;
  width: min(100%, 520px);
  aspect-ratio: 1;
  margin: 0 auto;
  border-radius: 28px;
  overflow: hidden;
  background: linear-gradient(180deg, #dce8f8 0%, #b9c9de 100%);
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.5);
  cursor: grab;
  touch-action: none;
  user-select: none;
}

.customer-profile-cropper-surface.is-loading {
  cursor: wait;
}

.customer-profile-cropper-surface:active {
  cursor: grabbing;
}

.customer-profile-cropper-image {
  position: absolute;
  top: 50%;
  left: 50%;
  max-width: none;
  pointer-events: none;
  user-select: none;
}

.customer-profile-cropper-overlay {
  position: absolute;
  inset: 0;
  pointer-events: none;
}

.customer-profile-cropper-ring {
  position: absolute;
  inset: 7.5%;
  border-radius: 50%;
  box-shadow: 0 0 0 999px rgba(15, 23, 42, 0.58);
  border: 1px solid rgba(255, 255, 255, 0.88);
}

.customer-profile-cropper-ring::before,
.customer-profile-cropper-ring::after {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
}

.customer-profile-cropper-ring::before {
  left: 33.333%;
  right: 33.333%;
  border-left: 1px solid rgba(255, 255, 255, 0.45);
  border-right: 1px solid rgba(255, 255, 255, 0.45);
}

.customer-profile-cropper-ring::after {
  top: 33.333%;
  bottom: 33.333%;
  border-top: 1px solid rgba(255, 255, 255, 0.45);
  border-bottom: 1px solid rgba(255, 255, 255, 0.45);
}

