/* Patient/doctor interaction consistency */
:root {
  --dashboard-cta-radius: 60px;
  --dashboard-field-radius: 8px;
  --dashboard-field-inset: 6px;
  --dashboard-tag-radius: calc(var(--dashboard-field-radius) - var(--dashboard-field-inset));
}

.appointment-booking-cta,
.customer-mobile-appointment-booknow-btn.appointment-booking-cta {
  grid-template-columns: minmax(0, 1fr) 48px;
  width: 230px;
  min-height: 56px;
  margin-inline: auto;
  padding: 4px 4px 4px 24px;
  gap: 12px;
  border: 1px solid #0a2a5e;
  border-radius: var(--dashboard-cta-radius);
  color: #0a2a5e;
  font-family: "Product Sans", Arial, sans-serif;
  font-size: 16px;
  font-weight: 400;
  letter-spacing: -.02em;
}

.appointment-booking-cta-icon {
  width: 48px;
  height: 48px;
  flex-basis: 48px;
  border-radius: var(--dashboard-cta-radius);
  background: #0a2a5e;
}

.appointment-booking-cta-icon svg {
  width: 24px;
  height: 24px;
}

.customer-subscription-history-item {
  grid-template-columns: 12px minmax(0, 1fr) max-content;
}

.customer-subscription-history-icon {
  width: 12px;
  min-width: 12px;
  max-width: 12px;
  height: 12px;
  margin-top: 5px;
  border: 0;
}

.customer-mtm-token-input {
  --dashboard-field-radius: 8px;
  --dashboard-field-inset: 6px;
  border-radius: var(--dashboard-field-radius);
}

.customer-mtm-token {
  border-radius: var(--dashboard-tag-radius);
}

.customer-mobile-field select,
.customer-mtm-mobile-flow select {
  min-height: 56px;
  height: 56px;
  padding-block: 0;
}

.customer-mobile-drawer-layer {
  display: block;
  visibility: hidden;
  opacity: 0;
  pointer-events: none;
  transition: visibility 0s linear 260ms, opacity 220ms ease;
}

.customer-mobile-drawer-layer.open {
  visibility: visible;
  opacity: 1;
  pointer-events: auto;
  transition-delay: 0s;
}

.customer-mobile-drawer {
  transform: translateX(-102%);
  transition: transform 260ms cubic-bezier(.22, 1, .36, 1);
}

.customer-mobile-drawer-layer.open .customer-mobile-drawer {
  transform: translateX(0);
}

.customer-mobile-drawer-backdrop {
  opacity: 0;
  transition: opacity 220ms ease;
}

.customer-mobile-drawer-layer.open .customer-mobile-drawer-backdrop {
  opacity: 1;
}

@media (max-width: 620px) {

  .appointment-booking-cta,
  .customer-mobile-appointment-booknow-btn.appointment-booking-cta {
    grid-template-columns: minmax(0, 1fr) 48px;
