/* reCAPTCHA v3 permits hiding its floating badge when this disclosure is
   displayed beside every protected public form. */
.grecaptcha-badge {
  visibility: hidden !important;
}

.recaptcha-disclosure {
  max-width: 430px;
  margin: 14px auto 0;
  color: #66758d;
  font-size: 11px;
  line-height: 1.5;
  text-align: center;
}

.recaptcha-disclosure a {
  color: #214f88;
  text-decoration: underline;
  text-underline-offset: 2px;
}

.recaptcha-disclosure a:hover {
  color: #0b326c;
}

/* Shared admin page hierarchy: title, metrics, then operational details. */
.nevari-admin-storefront .admin-page-heading {
  display: grid;
  gap: 6px;
  margin: 0;
}

.session-reauth-layer {
  position: fixed;
  inset: 0;
  z-index: 100000;
  display: grid;
  place-items: center;
  padding: 24px;
  background: linear-gradient(180deg, #fbfbfc 0%, #fbfbfc 62%, #dce8ff 100%);
}

.session-reauth-dialog {
  width: min(526px, 100%);
  max-height: calc(100vh - 48px);
  overflow: auto;
  padding: 24px 26px 32px;
  border: 1px solid #e1e6ef;
  border-radius: 34px;
  background: #fff;
  box-shadow: none;
}

.session-reauth-dialog h1 {
  margin: 0 0 22px;
  color: #050505;
  font-family: "Product Sans", "Google Sans", Arial, sans-serif;
  font-size: 42px;
  font-weight: 400;
  line-height: 1.05;
  letter-spacing: -0.04em;
}

.session-reauth-copy {
  margin: -8px 0 22px;
  color: #4d5665;
  line-height: 1.5;
}

.session-reauth-form {
  display: grid;
  gap: 20px;
}

.session-reauth-form > .auth-primary-button {
  width: 100%;
  min-height: 61px;
  margin-top: 14px;
  border-radius: 999px;
  font-size: 15px;
}

.session-reauth-form > .auth-google-panel {
  width: min(400px, calc(100% - 72px));
  margin: 18px auto 0;
}

.session-reauth-form label {
  display: grid;
  gap: 12px;
  color: #3e3e3e;
  font-size: 17px;
  font-weight: 400;
}

.session-reauth-form input {
  width: 100%;
  min-height: 51px;
  padding: 0 18px;
  border: 1px solid #bdcdea;
  border-radius: 10px;
  color: #111;
  background: #edf3fc;
  font: inherit;
}

.session-reauth-form input:focus {
  border-color: #7da9ea;
  outline: 3px solid rgba(55, 125, 230, 0.15);
}

.session-reauth-password-field {
  position: relative;
  display: block;
}

.session-reauth-password-field input {
  padding-right: 72px;
}

.session-reauth-password-field button {
  position: absolute;
  top: 50%;
  right: 12px;
  min-width: 44px;
  min-height: 44px;
  border: 0;
  color: #647089;
  background: transparent;
  font: inherit;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transform: translateY(-50%);
}

.session-reauth-links {
  display: flex;
  justify-content: center;
  gap: 14px;
  margin-top: 1px;
}

.session-reauth-links a {
  color: #111;
  font-size: 15px;
  text-decoration: underline;
  text-underline-offset: 3px;
}

.session-reauth-dialog .recaptcha-disclosure {
  max-width: 450px;
  margin: 20px auto 0;
  color: #5f718e;
  text-align: center;
}

.session-reauth-error {
  margin: 16px 0 0;
  padding: 11px 13px;
  border-radius: 10px;
  color: #8c2430;
  background: #fff0f1;
}

@media (max-width: 520px) {
  .session-reauth-layer { padding: 14px; }
  .session-reauth-dialog { padding: 24px 25px 30px; border-radius: 32px; }
  .session-reauth-dialog h1 { font-size: 40px; }
  .session-reauth-form > .auth-google-panel { width: calc(100% - 36px); }
}

.nevari-admin-storefront .admin-page-heading h1 {
  margin: 0;
  color: #0b326c;
  font-family: "Product Sans", "Google Sans", Arial, sans-serif;
  font-size: clamp(22px, 2vw, 28px);
  font-weight: 400;
  line-height: 1.2;
  letter-spacing: -0.025em;
}

.nevari-admin-storefront .admin-page-heading p {
  margin: 0;
  color: #526887;
  font-size: 13px;
  line-height: 1.5;
}

/* Shared admin page metrics: flat, quiet and consistent with Analytics. */
