.nevari-admin-storefront .admin-metric-card-blue {
  background: #f4f7fb;
}

.nevari-admin-storefront .admin-metric-card-sand {
  background: #f6f0e8;
}

.nevari-admin-storefront .admin-metric-card-mint {
  background: #dff5eb;
