/* Unified creation dialogs: order, appointment, and user account only.
   Dedicated root classes keep this layer independent from legacy modal overrides. */
:is(.nevari-create-order, .nevari-create-appointment, .nevari-create-user) {
  --create-modal-border: #dbe3ed;
  --create-modal-divider: #e8edf3;
  --create-modal-heading: #102f5f;
  --create-modal-text: #40516a;
  --create-modal-muted: #6f7d90;
  --create-modal-primary: #0a4f9f;
  position: relative;
  z-index: 1;
  width: min(1000px, calc(100vw - 32px));
  max-width: 1000px;
  max-height: calc(100dvh - 32px);
  overflow: hidden;
  border: 1px solid var(--create-modal-border);
  border-radius: 18px;
  background: #fff;
  background-image: none;
  box-shadow: none;
  color: var(--create-modal-text);
  font-weight: 400;
}

:is(.nevari-create-order, .nevari-create-appointment, .nevari-create-user)
  :is(.order-create-form, .creation-modal__form, .create-record-form) {
  display: flex;
  width: 100%;
  height: 100%;
  max-height: calc(100dvh - 34px);
  flex-direction: column;
  overflow: hidden;
  background: #fff;
}

:is(.nevari-create-order, .nevari-create-appointment, .nevari-create-user)
  :is(.modal-head, .creation-modal__header) {
  display: flex;
  min-height: 92px;
  flex: 0 0 auto;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 22px 30px;
  border-bottom: 1px solid var(--create-modal-divider);
  background: #fff;
  background-image: none;
  box-shadow: none;
}

:is(.nevari-create-order, .nevari-create-appointment, .nevari-create-user)
  :is(.modal-head, .creation-modal__header) h3 {
  margin: 0;
  color: var(--create-modal-heading);
  font-size: 26px;
  font-weight: 400;
  line-height: 1.2;
  letter-spacing: -.02em;
}

