/* Create user account */
.nevari-create-user {
  width: min(800px, calc(100vw - 32px));
}

.nevari-create-user .user-account-create {
  display: grid;
  gap: 24px;
}

.nevari-create-user .user-account-avatar-section {
  display: flex;
  align-items: center;
  gap: 18px;
  padding-bottom: 22px;
  border-bottom: 1px solid var(--create-modal-divider);
